window.TADABBUR_QAF = {"_meta":{"description":"تدبّر سورة ق (٥٠)، وسورةٌ مكّيّةٌ، كان النبيُّ ﷺ يقرؤها في العيدِ والجمعة. محورُها تقريرُ البعثِ والنشورِ بالأدلّةِ من خلقِ السماءِ والأرضِ وإحياءِ الأرضِ الميتة، والتذكيرُ بمصارعِ المكذّبين، وقربِ الله من العبدِ وكتابةِ الملكين لأقواله، ومشاهدِ الموتِ والحسابِ والجنّةِ والنار، والأمرِ بالصبرِ والتسبيحِ والتذكيرِ بالقرآن. فيها «ونحن أقرب إليه من حبل الوريد»، و«ما يلفظ من قول إلا لديه رقيب عتيد»، و«لمن كان له قلب أو ألقى السمع وهو شهيد»، و«فذكر بالقرآن من يخاف وعيد».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":50,"name":"ق","total_ayahs":45,"audio":[1,6,16,19,22,30,31,37,43,45],"passages":[{"title":"القسمُ بالقرآن، واستبعادُ البعث، والردُّ عليهم","range":[1,5],"theme":"القسمُ بالقرآنِ المجيد، وعجبُ الكفّارِ من مجيءِ منذرٍ منهم واستبعادِهم البعثَ بعد صيرورتهم ترابًا، والردُّ بأنّ الله يعلم ما تنقص الأرضُ منهم وعنده كتابٌ حفيظ، بل كذّبوا بالحقِّ فهم في أمرٍ مريج","verses":[{"n":1,"reflection":{"text":"«ق والقرآن المجيد»: «ق» حرفٌ مقطّع، أقسم الله بالقرآنِ المجيدِ العظيمِ الكريم؛ ففي هذا تعظيمُ القرآن؛ فعظّم القرآنَ الذي أقسم الله به ووصفه بالمجد، فالقرآنُ مجيدٌ كثيرُ الخيرِ والبركة، فاعتنِ به تلاوةً وتدبّرًا وعملًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ المجيدِ والاعتناءُ به."},"action":{"text":"تأمّل قسمَ الله بالقرآن: «ق» من الحروفِ المقطّعةِ التي هي من المتشابه؛ وأقسم الله بالقرآنِ المجيدِ، العظيمِ الكريمِ الكثيرِ الخيرِ والبركةِ والعلوم «ق والقرآن المجيد»؛ ففي هذا تعظيمُ شأنِ القرآنِ ووصفُه بالمجد؛ فأقسم الله به تعظيمًا لشأنه؛ فعظّم أنت القرآنَ الذي أقسم الله به ووصفه بالمجدِ والعظمة؛ فهو كتابٌ مجيدٌ كريمٌ كثيرُ الخير؛ إنه لقرآنٌ كريم؛ بل هو قرآنٌ مجيد في لوحٍ محفوظ؛ فاعتنِ بالقرآنِ تلاوةً وتدبّرًا وعملًا وتحكيمًا؛ فمن عظّم القرآنَ وأقبل عليه اهتدى؛ فاجعل للقرآنِ المجيدِ في قلبك مكانته اللائقة؛ فبتعظيمِ القرآنِ والعملِ به تُنال الهدايةُ والسعادة."}},{"n":2,"reflection":{"text":"«بل عجبوا أن جاءهم منذر منهم فقال الكافرون هذا شيء عجيب»: بل عجب المشركون أن جاءهم منذرٌ من جنسهم، فقال الكافرون: هذا شيءٌ عجيب؛ ففي هذا بيانُ استغرابهم لبعثةِ الرسولِ البشري؛ فلا تستغرب أن يكون الرسولُ بشرًا مثلك، فهذا أبلغُ في الحجّةِ والاقتداء، فاقبل رسالةَ النبيِّ البشري ولا تعجب منها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ رسالةِ الرسولِ البشري، وتركُ الاستغرابِ منها."},"action":{"text":"تأمّل استغرابَ المشركين: بل عجب هؤلاء المشركون أن جاءهم منذرٌ ورسولٌ من جنسهم وبشرٌ مثلهم، ينذرهم عذابَ الله؛ فقال الكافرون: هذا شيءٌ عجيبٌ غريب، كيف يكون الرسولُ بشرًا مثلنا؟ «بل عجبوا أن جاءهم منذر منهم فقال الكافرون هذا شيء عجيب»؛ ففي هذا بيانُ استغرابِ المشركين لبعثةِ رسولٍ بشريٍّ منهم؛ فتعجّبوا من كونِ الرسولِ بشرًا؛ ولا عجبَ في ذلك، بل هو الحكمةُ ليكون أقربَ لهم وأبلغَ في الاقتداء؛ فلا تستغرب أنت أن يكون الرسولُ بشرًا مثلك؛ فهذا أبلغُ في الحجّةِ وأيسرُ للاقتداءِ به؛ قل لو كان في الأرضِ ملائكةٌ يمشون مطمئنّين لنزّلنا عليهم من السماءِ ملكًا رسولًا؛ وما منع الناسَ أن يؤمنوا... إلا أن قالوا أبعث الله بشرًا رسولًا؛ فاقبل رسالةَ النبيِّ ﷺ البشري، واتّبعه؛ فمن قبل الرسولَ البشريَّ واتّبعه اهتدى، ومن استغرب ذلك وردّه ضلّ؛ فاجعل قبولَ رسالةِ الرسولِ واتّباعَه دأبك."}},{"n":3,"reflection":{"text":"«أإذا متنا وكنا ترابا ذلك رجع بعيد»: أإذا متنا وصرنا ترابًا نُبعَث؟ ذلك رجعٌ بعيدٌ مستبعَد؛ ففي هذا حكايةُ استبعادهم للبعث؛ فلا تستبعد البعثَ فإنه قريبٌ على الله يسير، فمن خلقك من العدمِ قادرٌ على إعادتك، فأيقن بالبعثِ ولا تستبعده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ وعدمُ استبعاده، وإدراكُ قدرةِ الله."},"action":{"text":"تأمّل استبعادَ المشركين للبعث: قال المشركون منكرين مستبعدين: أإذا متنا وبلينا وصرنا ترابًا نُبعَث ونُعاد أحياءً؟ ذلك رجعٌ وإعادةٌ بعيدةٌ مستبعَدةٌ في نظرنا، لا تكون «أإذا متنا وكنا ترابا ذلك رجع بعيد»؛ ففي هذا حكايةُ استبعادِ المشركين للبعثِ بعد الموتِ والبلى؛ فاستبعدوا إعادةَ الخلقِ بعد صيرورتهم ترابًا؛ فلا تستبعد أنت البعثَ والإعادة، فإنها قريبةٌ على الله يسيرة؛ فالذي خلقك من عدمٍ قادرٌ على إعادتك بعد الموت؛ وهو الذي يبدأ الخلقَ ثم يعيده وهو أهونُ عليه؛ كما بدأكم تعودون؛ قل يحييها الذي أنشأها أوّلَ مرّة؛ فأيقن بالبعثِ يقينًا جازمًا، ولا تستبعده كما استبعده المشركون؛ إنهم يرونه بعيدًا ونراه قريبًا؛ فمن أيقن بالبعثِ عمل له، ومن استبعده غفل وخسر؛ فاجعل يقينك بالبعثِ راسخًا، وعدمَ استبعاده دأبك؛ فبالإيمانِ بالبعثِ تعمل للآخرة."}},{"n":4,"reflection":{"text":"«قد علمنا ما تنقص الأرض منهم وعندنا كتاب حفيظ»: قد علمنا ما تأكل الأرضُ من أجسادهم، وعندنا كتابٌ حافظٌ لكلِّ شيء؛ ففي هذا ردٌّ على منكري البعثِ بإحاطةِ علمِ الله؛ فاعلم أنّ الله يعلم كلَّ ذرّةٍ من جسدك أينما كانت، فالبعثُ يسيرٌ على العليمِ الحفيظ، فأيقن بقدرةِ الله وعلمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بإحاطةِ علمِ الله وقدرته على البعث."},"action":{"text":"تأمّل الردَّ على منكري البعث: قد علمنا وأحطنا علمًا بما تنقص الأرضُ وتأكل من أجسادهم بعد موتهم، فلا يغيب عنّا منها شيء؛ وعندنا كتابٌ حفيظٌ حافظٌ لكلِّ ما كان ويكون، مُثبَتٌ فيه كلُّ شيء «قد علمنا ما تنقص الأرض منهم وعندنا كتاب حفيظ»؛ ففي هذا ردٌّ على منكري البعثِ الذين استبعدوه بعد صيرورتهم ترابًا؛ فبيّن أنّ الله يعلم ما تأكله الأرضُ من أجسادهم؛ فكيف يستبعدون البعثَ وهو محيطٌ بكلِّ شيء؟ فاعلم أنّ الله يعلم كلَّ ذرّةٍ من جسدك أينما تفرّقت في الأرض؛ لا يعزب عنه مثقالُ ذرّةٍ في السماواتِ ولا في الأرض؛ وما يعزب عن ربّك من مثقالِ ذرّة؛ وعنده مفاتحُ الغيبِ لا يعلمها إلا هو؛ فالبعثُ يسيرٌ على الله العليمِ الحفيظ؛ فأيقن بعلمِ الله المحيطِ وقدرته على البعث؛ فمن أيقن بذلك عمل للآخرة، ومن جهله أنكر البعث؛ فاجعل يقينك بإحاطةِ علمِ الله وقدرته راسخًا؛ فبه تؤمن بالبعثِ وتستعدّ له."}},{"n":5,"reflection":{"text":"«بل كذبوا بالحق لما جاءهم فهم في أمر مريج»: بل كذّبوا بالقرآنِ الحقِّ لمّا جاءهم، فهم في أمرٍ مضطربٍ مختلط؛ ففي هذا بيانُ اضطرابِ المكذّبين وحيرتهم؛ فاحذر تكذيبَ الحقِّ فإنه يورث الاضطرابَ والحيرة، فاقبل الحقَّ لتثبت وتستقرّ، فالتكذيبُ يورث القلقَ والتخبّط.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ للثباتِ والاستقرار، والحذرُ من التكذيبِ الموجبِ للحيرة."},"action":{"text":"تأمّل اضطرابَ المكذّبين: بل كذّب هؤلاء المشركون بالحقِّ، وهو القرآنُ والرسالة، لمّا جاءهم، من غيرِ تأمّلٍ ولا نظر؛ فهم في أمرٍ مريجٍ مختلطٍ مضطربٍ حائر؛ فمرّةً يقولون ساحر، ومرّةً شاعر، ومرّةً مجنون؛ فتخبّطوا واضطربوا «بل كذبوا بالحق لما جاءهم فهم في أمر مريج»؛ ففي هذا بيانُ أنّ تكذيبَ الحقِّ يورث الاضطرابَ والحيرةَ والتخبّط؛ فلمّا كذّبوا بالحقِّ اضطربت أقوالهم وتناقضت؛ فاحذر أنت تكذيبَ الحقِّ فإنه يورث القلقَ والحيرةَ والتخبّط؛ فاقبل الحقَّ عند وضوحه لتثبت وتستقرّ وتطمئنّ؛ فأهلُ الحقِّ على بصيرةٍ وثبات، وأهلُ الباطلِ في حيرةٍ واضطراب؛ يكادُ سنا برقه يذهب بالأبصار؛ فمن قبل الحقَّ ثبت واطمأنّ، ومن كذّب به اضطرب وتخبّط؛ فاجعل قبولَ الحقِّ سبيلَ ثباتك واستقرارك؛ فبقبولِ الحقِّ تسلم من الحيرةِ والاضطراب."}}]},{"title":"الاستدلالُ بخلقِ السماءِ والأرضِ وإحياءِ الأرضِ على البعث","range":[6,11],"theme":"دعوةُ الكفّارِ للنظرِ في بناءِ السماءِ بلا فروجٍ وزينتها، ومدِّ الأرضِ وإرسائها بالجبالِ وإنباتِ كلِّ زوجٍ بهيجٍ تبصرةً للمنيبين، وإنزالِ الماءِ المباركِ لإنباتِ الجنّاتِ والحبِّ والنخل، وأنّ إحياءَ الأرضِ الميتةِ دليلُ الخروجِ والبعث","verses":[{"n":6,"reflection":{"text":"«أفلم ينظروا إلى السماء فوقهم كيف بنيناها وزيناها وما لها من فروج»: أفلم ينظروا إلى السماءِ فوقهم كيف بنيناها وزيّنّاها بالنجومِ وما لها من شقوقٍ ولا فطور؟ ففي هذا الاستدلالُ بخلقِ السماءِ على قدرةِ البعث؛ فتأمّل السماءَ المحكمةَ البناءِ المزيّنة، فمن خلقها قادرٌ على بعثك، فالنظرُ في خلقِ السماءِ يورث اليقينَ بالبعث.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في خلقِ السماءِ للاستدلالِ على قدرةِ الله والبعث."},"action":{"text":"تأمّل الاستدلالَ بخلقِ السماء: أفلم ينظر هؤلاء المنكرون للبعثِ إلى السماءِ فوقهم، كيف بنيناها بناءً محكمًا بلا عمد؛ وزيّنّاها بالنجومِ والكواكب؛ وما لها من فروجٍ وشقوقٍ وصدوعٍ وعيوب؟ «أفلم ينظروا إلى السماء فوقهم كيف بنيناها وزيناها وما لها من فروج»؛ ففي هذا الاستدلالُ بخلقِ السماءِ المحكمِ على قدرةِ الله على البعث؛ فالذي خلق السماءَ العظيمةَ بلا عمدٍ ولا فطورٍ قادرٌ على إعادةِ الخلق؛ فتأمّل أنت السماءَ المحكمةَ البناءِ، المزيّنةَ بالنجوم، الخاليةَ من العيوبِ والشقوق؛ فارجعِ البصرَ هل ترى من فطور، ثم ارجعِ البصرَ كرّتين ينقلب إليك البصرُ خاسئًا وهو حسير؛ أأنتم أشدُّ خلقًا أم السماءُ بناها؛ فمن خلق السماءَ العظيمةَ قادرٌ على بعثك وإعادتك؛ فالنظرُ والتفكّرُ في خلقِ السماءِ يورث اليقينَ بقدرةِ الله والبعث؛ فمن تفكّر في خلقِ السماءِ أيقن بالخالقِ وبالبعث؛ فاجعل التفكّرَ في خلقِ السماءِ سبيلَ يقينك بقدرةِ الله وبالبعث."}},{"n":7,"reflection":{"text":"«والأرض مددناها وألقينا فيها رواسي وأنبتنا فيها من كل زوج بهيج»، والأرضَ بسطناها وألقينا فيها جبالًا راسيات، وأنبتنا فيها من كلِّ صنفٍ حسنٍ بهيج؛ ففي هذا الاستدلالُ بخلقِ الأرضِ وزينتها؛ فتأمّل الأرضَ الممدودةَ الثابتةَ المزيّنةَ بالنبات، فمن خلقها قادرٌ على بعثك، فالنظرُ في خلقِ الأرضِ يورث اليقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في خلقِ الأرضِ ونباتها للاستدلالِ على قدرةِ الله."},"action":{"text":"تأمّل الاستدلالَ بخلقِ الأرض: والأرضَ مددناها وبسطناها لتستقرّوا عليها؛ وألقينا فيها رواسيَ، جبالًا ثوابتَ ترسّيها لئلا تميد بكم؛ وأنبتنا فيها من كلِّ زوجٍ وصنفٍ بهيجٍ حسنِ المنظرِ يسرُّ الناظرين «والأرض مددناها وألقينا فيها رواسي وأنبتنا فيها من كل زوج بهيج»؛ ففي هذا الاستدلالُ بخلقِ الأرضِ وتثبيتها بالجبالِ وإنباتِ النباتِ الحسنِ فيها على قدرةِ الله؛ فمن مدَّ الأرضَ وأرساها وأنبت فيها قادرٌ على البعث؛ فتأمّل أنت الأرضَ الممدودةَ الثابتةَ بالجبال، المزيّنةَ بأصنافِ النباتِ الحسن؛ وألقى في الأرضِ رواسيَ أن تميد بكم؛ وأنبتنا فيها من كلِّ زوجٍ كريم؛ ومن آياته أنك ترى الأرضَ خاشعةً فإذا أنزلنا عليها الماءَ اهتزّت وربت، إنّ الذي أحياها لمحيي الموتى؛ فالنظرُ في خلقِ الأرضِ ونباتها يورث اليقينَ بقدرةِ الله والبعث؛ فمن تفكّر في خلقِ الأرضِ أيقن بالخالقِ وبالبعث؛ فاجعل التفكّرَ في خلقِ الأرضِ وزينتها سبيلَ يقينك بقدرةِ الله."}},{"n":8,"reflection":{"text":"«تبصرة وذكرى لكل عبد منيب»: جعلنا ذلك تبصرةً وتذكرةً لكلِّ عبدٍ رجّاعٍ إلى الله؛ ففي هذا بيانُ أنّ آياتِ الله عبرةٌ للمنيبين؛ فتبصّر بآياتِ الله وتذكّر بها، وكن عبدًا منيبًا رجّاعًا إلى الله، فآياتُ الله تنفع أهلَ الإنابةِ والتبصّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التبصّرُ بآياتِ الله والإنابةُ إليه، والانتفاعُ بها."},"action":{"text":"تأمّل أنّ الآياتِ عبرةٌ للمنيبين: جعلنا خلقَ السماواتِ والأرضِ وما فيها من العجائبِ والنبات، تبصرةً، أي إبصارًا وبيانًا للحق ،؛ وذكرى، تذكرةً وعبرةً، لكلِّ عبدٍ منيبٍ رجّاعٍ إلى الله بقلبه «تبصرة وذكرى لكل عبد منيب»؛ ففي هذا بيانُ أنّ آياتِ الله في الخلقِ تبصرةٌ وذكرى، لكن ينتفع بها العبدُ المنيبُ الرجّاعُ إلى الله؛ فالآياتُ معروضةٌ للجميع، لكن المنتفعُ بها أهلُ الإنابة؛ فتبصّر أنت بآياتِ الله في الخلق، وتذكّر بها قدرةَ الله ووحدانيته والبعث؛ وكن عبدًا منيبًا رجّاعًا إلى الله بالتوبةِ والطاعةِ والإقبالِ عليه؛ وأنيبوا إلى ربّكم وأسلموا له؛ ومن يهدي إليه من ينيب؛ فآياتُ الله تنفع أهلَ الإنابةِ والتبصّرِ والتذكّر؛ فمن أناب وتبصّر انتفع بالآيات، ومن أعرض لم تنفعه؛ فاجعل التبصّرَ بآياتِ الله والإنابةَ إليه دأبك؛ فبالتبصّرِ والإنابةِ تنتفع بآياتِ الله."}},{"n":9,"reflection":{"text":"«ونزلنا من السماء ماء مباركا فأنبتنا به جنات وحب الحصيد»، ونزّلنا من السماءِ ماءً كثيرَ الخيرِ والبركة، فأنبتنا به بساتينَ وحبَّ الزرعِ الذي يُحصَد؛ ففي هذا بيانُ نعمةِ المطرِ وثمرتِه؛ فاشكر الله على نعمةِ المطرِ والزرع، فبهما حياتك ورزقك، فالماءُ المباركُ نعمةٌ تستوجب الشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ المطرِ والزرع، وإدراكُ بركةِ الماء."},"action":{"text":"تأمّل نعمةَ المطرِ وثمرتَه: ونزّلنا من السماءِ ماءً مباركًا كثيرَ الخيرِ والنفعِ والبركة؛ فأنبتنا به جنّاتٍ وبساتينَ من الأشجارِ والثمار؛ وحبَّ الحصيدِ، أي الحبَّ الذي يُحصَد كالبرِّ والشعيرِ وسائرِ الحبوب «ونزلنا من السماء ماء مباركا فأنبتنا به جنات وحب الحصيد»؛ ففي هذا بيانُ نعمةِ إنزالِ المطرِ المباركِ وإنباتِ الجنّاتِ والحبوبِ به؛ فبالماءِ المباركِ تحيا الأرضُ وينبت الزرعُ ويحصل الرزق؛ فاشكر أنت الله على نعمةِ المطرِ والزرعِ والثمار؛ فبهما حياتك ورزقك وقوامُ معاشك؛ أفرأيتم الماءَ الذي تشربون، أأنتم أنزلتموه من المزنِ أم نحن المنزلون؛ فأنبتنا فيها حبًّا وعنبًا وقضبًا؛ فالماءُ المباركُ من أعظمِ نعمِ الله على العباد؛ فمن شكر نعمةَ الماءِ والزرعِ زاده الله، ومن كفرها سلبه؛ ولئن شكرتم لأزيدنّكم؛ فاجعل شكرَ نعمةِ المطرِ والزرعِ واستعمالها في الطاعةِ دأبك."}},{"n":10,"reflection":{"text":"«والنخل باسقات لها طلع نضيد»، والنخلَ الطوالَ لها طلعٌ متراكبٌ منضود؛ ففي هذا بيانُ نعمةِ النخلِ وثمره؛ فتأمّل خلقَ النخلِ الباسقاتِ وثمرها المنضود، فهي آيةٌ ونعمة، فاشكر الله واعتبر بخلقه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في خلقِ النخلِ وشكرُ نعمته."},"action":{"text":"تأمّل نعمةَ النخل: وأنبتنا النخلَ باسقاتٍ، أي طوالًا شاهقاتٍ في السماء؛ لها طلعٌ، وهو أوّلُ ما يخرج من ثمرها، نضيدٌ متراكبٌ منضودٌ بعضه فوق بعض «والنخل باسقات لها طلع نضيد»؛ ففي هذا بيانُ نعمةِ خلقِ النخلِ الطوالِ وثمرها المنضود، وأنها آيةٌ على قدرةِ الله؛ فالنخلُ الباسقاتُ بطلعها المنضودِ آيةٌ ونعمة؛ فتأمّل أنت خلقَ النخلِ الشاهقةِ وثمرها المتراكبِ المنضود؛ فهي آيةٌ على قدرةِ الله وحكمته، ونعمةٌ على العباد؛ وجنّاتٍ من أعنابٍ والنخلَ صنوانًا وغيرَ صنوان؛ وهو الذي أنشأ جنّاتٍ معروشاتٍ وغيرَ معروشات والنخلَ؛ كلوا من ثمره إذا أثمر؛ فمن تأمّل خلقَ النخلِ وثمرها اعتبر بقدرةِ الله وشكر نعمته؛ فاجعل التأمّلَ في خلقِ النخلِ وشكرَ نعمته دأبك؛ فبالتأمّلِ في آياتِ الله تعرف قدرته، وبالشكرِ تدوم النعم."}},{"n":11,"reflection":{"text":"«رزقا للعباد وأحيينا به بلدة ميتا كذلك الخروج»: جعلنا ذلك رزقًا للعباد، وأحيينا بالماءِ بلدةً ميتة، كذلك يكون الخروجُ من القبور؛ ففي هذا الاستدلالُ بإحياءِ الأرضِ على البعث؛ فاعتبر بإحياءِ الأرضِ الميتةِ بالمطر، فكما تحيا الأرضُ يحيا الموتى، فأيقن بالبعثِ من دليلِ إحياءِ الأرض.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ من دليلِ إحياءِ الأرضِ الميتة."},"action":{"text":"تأمّل الاستدلالَ بإحياءِ الأرضِ على البعث: جعلنا هذا النباتَ والثمرَ رزقًا للعبادِ يتغذّون به؛ وأحيينا بذلك الماءِ بلدةً ميتةً هامدةً لا نباتَ فيها، فأنبتت واخضرّت؛ كذلك، كما أحيينا الأرضَ الميتة، يكون الخروجُ والبعثُ من القبور «رزقا للعباد وأحيينا به بلدة ميتا كذلك الخروج»؛ ففي هذا الاستدلالُ بإحياءِ الأرضِ الميتةِ بالمطرِ على البعثِ والنشور؛ فكما تحيا الأرضُ بعد موتها، يحيا الموتى بعد فنائهم؛ فاعتبر أنت بإحياءِ الأرضِ الميتةِ بالمطر؛ فهو دليلٌ محسوسٌ على البعث؛ فمن قدر على إحياءِ الأرضِ قادرٌ على إحياءِ الموتى؛ ومن آياته أنك ترى الأرضَ خاشعةً فإذا أنزلنا عليها الماءَ اهتزّت وربت، إنّ الذي أحياها لمحيي الموتى إنه على كلِّ شيءٍ قدير؛ فأحيينا به بلدةً ميتًا كذلك النشور؛ فأيقن بالبعثِ من دليلِ إحياءِ الأرض؛ فمن اعتبر بإحياءِ الأرضِ أيقن بالبعث، ومن غفل أنكره؛ فاجعل الاعتبارَ بإحياءِ الأرضِ سبيلَ يقينك بالبعث."}}]},{"title":"مصارعُ المكذّبين، والاحتجاجُ بالخلقِ الأول","range":[12,15],"theme":"التذكيرُ بتكذيبِ قومِ نوحٍ وأصحابِ الرسِّ وثمودَ وعادٍ وفرعونَ وقومِ لوطٍ وأصحابِ الأيكةِ وقومِ تبّعٍ فحقّ عليهم الوعيد، والاحتجاجُ على البعثِ بأنّ الله لم يعجز بالخلقِ الأولِ فكيف يعجز عن الإعادة، بل هم في لبسٍ من خلقٍ جديد","verses":[{"n":12,"reflection":{"text":"«كذبت قبلهم قوم نوح وأصحاب الرس وثمود»: كذّبت قبل هؤلاء قومُ نوحٍ وأصحابُ الرسِّ وثمود؛ ففي هذا التذكيرُ بمصارعِ المكذّبين؛ فاعتبر بمصيرِ المكذّبين قبلك، فالتكذيبُ سنّةُ الهالكين، فاحذر أن تسلك سبيلهم فيصيبك ما أصابهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ المكذّبين، والحذرُ من سبيلهم."},"action":{"text":"تأمّل التذكيرَ بمصارعِ المكذّبين: كذّبت قبل هؤلاء المشركين من قريشٍ أممٌ كثيرة: قومُ نوحٍ الذين أغرقهم الله بالطوفان؛ وأصحابُ الرسِّ، وهم قومٌ كذّبوا نبيّهم؛ وثمودُ قومُ صالحٍ الذين أهلكهم الله بالصيحة «كذبت قبلهم قوم نوح وأصحاب الرس وثمود»؛ ففي هذا التذكيرُ بمصارعِ الأممِ المكذّبةِ قبل قريش، تسليةً للنبيِّ وتحذيرًا لهم؛ فكذّبت هذه الأممُ رسلها فأهلكها الله؛ فاعتبر أنت بمصيرِ المكذّبين قبلك؛ فالتكذيبُ سنّةُ الهالكين وطريقُ المعذّبين؛ ألم يأتهم نبأُ الذين من قبلهم قومِ نوحٍ وعادٍ وثمود؛ فبادر بالإيمانِ والطاعة، واحذر أن تسلك سبيلَ المكذّبين فيصيبك ما أصابهم؛ فمن اعتبر بمصارعِ المكذّبين نجا، ومن سلك سبيلهم هلك؛ فاجعل من قصصِ المهلَكين عبرةً تحملك على الإيمانِ وتركِ التكذيب."}},{"n":13,"reflection":{"text":"«وعاد وفرعون وإخوان لوط»، وعادٌ قومُ هود، وفرعونُ، وإخوانُ لوطٍ (قومه)؛ ففي هذا تتمّةُ التذكيرِ بمصارعِ المكذّبين؛ فاعتبر بإهلاكِ عادٍ وفرعونَ وقومِ لوط، فكلُّهم أُهلِكوا بتكذيبهم، فاحذر التكذيبَ الذي أهلكهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بإهلاكِ المكذّبين، والحذرُ من التكذيب."},"action":{"text":"تأمّل تتمّةَ مصارعِ المكذّبين: وكذلك كذّبت عادٌ، قومُ هودٍ الذين أهلكهم الله بالريحِ الصرصر؛ وفرعونُ وقومه الذين أغرقهم الله؛ وإخوانُ لوطٍ، أي قومه، الذين أهلكهم الله بقلبِ ديارهم وإمطارِ الحجارة «وعاد وفرعون وإخوان لوط»؛ ففي هذا تتمّةُ التذكيرِ بمصارعِ الأممِ المكذّبة؛ فعادٌ وفرعونُ وقومُ لوطٍ كلُّهم كذّبوا رسلهم فأهلكهم الله بأنواعِ العذاب؛ فاعتبر أنت بإهلاكِ هذه الأمم؛ وكيف أُهلِكوا جميعًا بتكذيبهم؛ وعادًا وثمودَ وقد تبيّن لكم من مساكنهم؛ فأخذناهم بذنوبهم؛ فاحذر التكذيبَ الذي أهلكهم؛ فمن اعتبر بمصارعهم نجا، ومن كذّب مثلهم هلك؛ فاجعل من إهلاكِ المكذّبين عبرةً تحملك على الإيمانِ والطاعة."}},{"n":14,"reflection":{"text":"«وأصحاب الأيكة وقوم تبع كل كذب الرسل فحق وعيد»، وأصحابُ الأيكةِ (قومُ شعيب) وقومُ تبّع، كلٌّ كذّب الرسلَ فحقّ عليهم وعيدي؛ ففي هذا بيانُ أنّ عاقبةَ التكذيبِ نزولُ الوعيد؛ فاحذر تكذيبَ الرسلِ فإنه يوجب العذاب، فآمن بالرسلِ واتّبعهم، فتكذيبُ الرسلِ يحقّق الوعيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالرسلِ واتّباعُهم، والحذرُ من تكذيبهم."},"action":{"text":"تأمّل عاقبةَ التكذيب: وأصحابُ الأيكةِ، وهم قومُ شعيبٍ أصحابُ الشجرِ الملتفّ، الذين أهلكهم الله بعذابِ يومِ الظلّة؛ وقومُ تبّعٍ من أهلِ اليمن؛ كلُّ هؤلاء الأممِ كذّبوا الرسلَ الذين أُرسِلوا إليهم؛ فحقّ ووجب عليهم وعيدي وعذابي الذي توعّدتهم به «وأصحاب الأيكة وقوم تبع كل كذب الرسل فحق وعيد»؛ ففي هذا بيانُ أنّ كلَّ هذه الأممِ كذّبت الرسلَ فحقّ عليها الوعيدُ والعذاب؛ فعاقبةُ التكذيبِ نزولُ العذابِ المتوعَّدِ به؛ فاحذر أنت تكذيبَ الرسلِ وما جاؤوا به؛ فإنه يوجب حلولَ الوعيدِ والعذاب؛ فكذّبوه فأهلكناهم إنّ في ذلك لآية؛ وكلًّا ضربنا له الأمثالَ وكلًّا تبّرنا تتبيرًا؛ فآمن بالرسلِ واتّبع ما جاؤوا به؛ فمن آمن بالرسلِ نجا، ومن كذّبهم حقّ عليه الوعيد؛ فاجعل الإيمانَ بالرسلِ واتّباعَهم سبيلَ نجاتك من الوعيد."}},{"n":15,"reflection":{"text":"«أفعيينا بالخلق الأول بل هم في لبس من خلق جديد»: أفعجزنا وتعبنا بالخلقِ الأوّلِ حتى نعجز عن الإعادة؟ بل هم في شكٍّ ولبسٍ من خلقٍ جديد؛ ففي هذا الاحتجاجُ على البعثِ بالخلقِ الأول؛ فاعلم أنّ الذي خلقك أوّلًا لم يعجز، فالإعادةُ أهونُ عليه، فأيقن بالبعثِ فمن بدأ الخلقَ قادرٌ على إعادته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعث، والاحتجاجُ عليه بالخلقِ الأول."},"action":{"text":"تأمّل الاحتجاجَ بالخلقِ الأول: أفعجزنا وتعبنا بالخلقِ الأوّلِ حين خلقناهم أوّلَ مرّةٍ من عدم، حتى نعجز عن إعادتهم بعد الموت؟ لا؛ بل هم في لبسٍ وشكٍّ وحيرةٍ من خلقٍ جديدٍ وبعثٍ بعد الموت «أفعيينا بالخلق الأول بل هم في لبس من خلق جديد»؛ ففي هذا الاحتجاجُ على البعثِ بالخلقِ الأول؛ فالذي خلقهم أوّلًا من عدمٍ لم يعجز عن ذلك، فكيف يعجز عن الإعادة؟ بل الإعادةُ أهونُ من البدء؛ فاعلم أنت أنّ الذي خلقك أوّلَ مرّةٍ من عدمٍ لم يعجز ولم يتعب؛ فالإعادةُ أيسرُ عليه من البدء؛ وهو الذي يبدأ الخلقَ ثم يعيده وهو أهونُ عليه؛ كما بدأنا أوّلَ خلقٍ نعيده؛ أوليس الذي خلق السماواتِ والأرضَ بقادرٍ على أن يخلق مثلهم؛ فأيقن بالبعثِ يقينًا جازمًا؛ فمن بدأ خلقك قادرٌ على إعادتك؛ فمن أيقن بذلك آمن بالبعث، ومن شكّ فيه بقي في حيرة؛ فاجعل يقينك بأنّ من بدأ الخلقَ قادرٌ على إعادته راسخًا؛ فبه تؤمن بالبعثِ وتستعدّ له."}}]},{"title":"قربُ الله وكتابةُ الملكين، والموتُ والحشر","range":[16,22],"theme":"أنّ الله خلق الإنسانَ ويعلم وسوسةَ نفسه وهو أقربُ إليه من حبلِ الوريد، وأنّ الملكين يكتبان كلَّ قولٍ ولا يلفظ إلا لديه رقيبٌ عتيد، ومجيءِ سكرةِ الموتِ بالحق، والنفخِ في الصورِ يومَ الوعيد، ومجيءِ كلِّ نفسٍ معها سائقٌ وشهيد، وكشفِ الغطاءِ عن الغافلِ فبصره اليومَ حديد","verses":[{"n":16,"reflection":{"text":"«ولقد خلقنا الإنسان ونعلم ما توسوس به نفسه ونحن أقرب إليه من حبل الوريد»، ولقد خلقنا الإنسانَ ونعلم ما تحدّثه به نفسه، ونحن أقربُ إليه من حبلِ الوريدِ (عرقِ العنق)؛ ففي هذا بيانُ قربِ الله وإحاطةِ علمِه بأخفى الخواطر؛ فراقب الله في خواطرك وأسرارك، فهو أقربُ إليك من نفسك، فاستحضر قربَ الله وعلمَه بما في نفسك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في الخواطرِ والأسرار، واستحضارُ قربِه وعلمِه."},"action":{"text":"تأمّل قربَ الله وإحاطةَ علمه: ولقد خلقنا الإنسانَ ونحن نعلم ما توسوس وتحدّث به نفسه من الخواطرِ والأسرارِ الخفيّة؛ ونحن أقربُ إليه من حبلِ الوريدِ، وهو عرقٌ في العنقِ متّصلٌ بالقلب؛ فعلمُنا وقدرتُنا أقربُ إليه من ذلك «ولقد خلقنا الإنسان ونعلم ما توسوس به نفسه ونحن أقرب إليه من حبل الوريد»؛ ففي هذا بيانُ قربِ الله من العبدِ بعلمه وإحاطته، وأنه يعلم أخفى خواطرِ النفسِ وحديثها؛ فلا يخفى عليه شيءٌ من سرِّ العبدِ ونجواه؛ فراقب أنت الله في خواطرك وأسرارك وحديثِ نفسك؛ فهو أقربُ إليك من نفسك، يعلم ما توسوس به؛ يعلم السرَّ وأخفى؛ يعلم خائنةَ الأعينِ وما تخفي الصدور؛ وهو معكم أينما كنتم؛ فاستحضر قربَ الله وعلمَه بما في نفسك في كلِّ لحظة؛ فمن راقب الله في سرّه وخواطره استقام، ومن غفل عن قربه زلّ؛ فاجعل مراقبةَ الله في خواطرك واستحضارَ قربه وعلمه دأبك؛ فبمراقبته في السرِّ تصلح النفسُ ويستقيم القلب."},"qadiyya":{"title":"قضيّةُ القرب: «أقربُ إليه من حبل الوريد» وما يُبنى عليها","question":"قال الله: «**ولقد خلقنا الإنسان ونعلم ما توسوس به نفسُه، ونحن أقربُ إليه من حبل الوريد**».\n**فذُكر ثلاثةُ أمورٍ في نسق**: **الخلق، ثمّ العلمُ بما يُوسوس به في النفس، ثمّ القرب.**\nفالقضيّة: **ما «حبل الوريد» ولماذا خُصّ بالذكر؟** ثمّ: **ما الذي يُبنى على هذا الخبر عملًا؟ فإنّ الخبر إذا لم يُثمر عملًا كان معلومةً لا أكثر.**","background":"ولا يظهر موضعُ المثل حتى نعرف ما شُبّه به:\n**الوريدُ عرقٌ في العنق، وهو من أقرب ما يكون إلى الإنسان؛ فيه تجري حياتُه، وهو ملاصقٌ له لا ينفكّ عنه.**\n**فاختير أقربُ شيءٍ إلى الإنسان من نفسه، ثمّ قيل: بل أقرب.**\n**وموضعُ الدقّة أنّ الآية جمعت بين العلم بما في النفس وبين القرب.**\n**فلو ذُكر العلمُ وحدَه لأمكن أن يُتصوَّر عالمٌ من بعيد؛ فذُكر القربُ ليرتفع هذا التصوّر.**","what_happened":"**بيّن السعديُّ ما تضمّنته الآية على ترتيبها**: «**يخبر تعالى أنّه المتفرّد بخلق جنس الإنسان، ذكورِهم وإناثِهم، وأنّه يعلم أحوالَه، وما يسرّه ويوسوس في صدره**».\n**ثمّ فسّر حبل الوريد**: «**وأنّه أقربُ إليه من حبل الوريد، الذي هو أقربُ شيءٍ إلى الإنسان، وهو العرقُ المكتنف لثغرة النحر**».\n**⭐ ثمّ لم يقف عند الخبر، بل رتّب عليه ما يُعمل به**: «**وهذا ممّا يدعو الإنسانَ إلى مراقبة خالقه، المطّلع على ضميره وباطنه، القريب منه في جميع أحواله**».\n**⭐ ثمّ صاغ المراقبة في جملتين متقابلتين**:\n«**فيستحي منه أن يراه حيث نهاه، أو يفقده حيث أمره**».\n**ثمّ ألحق بذلك أدبًا مع الملائكة**: «**وكذلك ينبغي له أن يجعل الملائكةَ الكرامَ الكاتبين منه على بال، فيُجلّهم ويوقّرهم، ويحذر أن يفعل أو يقول ما يُكتب عنه ممّا لا يُرضي ربَّ العالمين**».","the_verdict":"**فالحاصلُ أنّ الآية خبرٌ سِيق ليُثمر مراقبة، وأنّ الإمام لم يتركه خبرًا.**\n**⭐ وأنفعُ ما في الموضع صياغتُه للمراقبة في شقّين**، **لأنّها تشمل ما يقع فيه الغلطُ من الجهتين:**\n«**أن يراه حيث نهاه**»: **وهذا هو الذي يخطر ببال الناس؛ أن يُرى وأنت تفعل ما نُهيتَ عنه.**\n«**أو يفقده حيث أمره**»: **وهذا هو الذي يُغفل عنه؛ أن يُطلب فلا يُوجد في موضعٍ أُمر بأن يكون فيه.**\n**فالأوّلُ محاسبةٌ على الفعل، والثاني محاسبةٌ على الغياب.**\n**وأكثرُ الناس يحاسب نفسَه على ما فعل، وقلّ من يحاسبها على أين لم يكن.**\n**⭐ وأمّا ذكرُ العلم بالوسوسة فموضعُه من الحجّة دقيق.**\n**فإنّ الوسوسة أخفى ما في الإنسان**: **حديثٌ في النفس لم يخرج إلى لسانٍ ولا جارحة، وقد لا يعرفه صاحبُه على وجهه.**\n**فإذا كان هذا معلومًا، فما فوقه أولى.**\n**فذكرُ الأخفى إثباتٌ لما هو أظهرُ منه بطريق الأولى.**\n**⭐ وأمّا الجمعُ بين الخلق والعلم فترتيبٌ في موضعه**: **فالصانعُ أعلمُ بصنعته، كما مرّ في الروم: «لأنّ الخالق لا بدّ أن يعلم ما خلقه».** **فالعلمُ بما في النفس ليس دعوى؛ إنّه لازمٌ للخلق.**\n**⭐ وأمّا القربُ فينبغي أن يُفهم على ما يليق به سبحانه**، **كما قاله الإمامُ: «القريب منه في جميع أحواله»**؛ **والمقصودُ في هذا الموضع أثرُه: أنّه لا يغيب عنك ولا تغيب عنه.**","for_you":"**فأمّا الذي تخرج به فثلاثة:**\n**الأوّل: حاسب نفسك على الغياب كما تحاسبها على الفعل.** **فقد جمع الإمامُ الشقّين: «أن يراه حيث نهاه، أو يفقده حيث أمره».** **فاسأل في آخر يومك: أين كان ينبغي أن أكون ولم أكن؟** **فهذا نصفُ المراقبة، وأكثرُ الناس يتركه.**\n**والثاني: ابدأ الإصلاح من الخاطر لا من الفعل.** **فقد ذُكر في الآية العلمُ بالوسوسة قبل كلّ شيء.** **فما تُحدّث به نفسَك معلومٌ قبل أن يصير عملًا؛ والذي يعالج الفعلَ وحدَه يعالج الفرع.**\n**والثالث: اجعل هذا الخبر عملًا لا معلومة.** **فقد كان يمكن أن يُقرأ الخبرُ فيُعجَب به ثمّ يُطوى.** **وقد رتّب عليه الإمامُ المراقبة؛ فانظر في كلّ خبرٍ في القرآن: ماذا يُبنى عليه؟** **فإنّ الخبر الذي لا يتغيّر به عملُك لم يبلغ منك مبلغَه.**","grade":"ma'thur","source":"بيانُ السعديّ لما تضمّنته الآية («يخبر تعالى، أنه المتفرد بخلق جنس الإنسان، ذكورهم وإناثهم، وأنه يعلم أحواله، وما يسره، ويوسوس في صدره»)، وتفسيرُه حبلَ الوريد («الذي هو أقرب شيء إلى الإنسان، وهو العرق المكتنف لثغرة النحر»)، وترتيبُه العملَ على الخبر («وهذا مما يدعو الإنسان إلى مراقبة خالقه، المطلع على ضميره وباطنه، القريب منه في جميع أحواله»)، وصياغتُه للمراقبة («فيستحي منه أن يراه، حيث نهاه، أو يفقده، حيث أمره»)، وأدبُه مع الملائكة («وكذلك ينبغي له أن يجعل الملائكة الكرام الكاتبين منه على بال، فيجلهم ويوقرهم»): كلُّها بنصّها في تفسير السعديّ (٥٠:١٦).","honesty":"وممّا يجب أن يُقال:\n**قولُنا إنّ ذكر الأخفى إثباتٌ لما هو أظهرُ منه بطريق الأولى، فتحريرٌ منّا على نظم الآية، لا نصٌّ لإمامٍ ها هنا.**\n**وأمّا قولُنا إنّ أكثر الناس يحاسب نفسَه على ما فعل وقلّ من يحاسبها على أين لم يكن، فوصفٌ لواقعٍ نراه، لا إحصاءَ عندنا به.**\n**وأمّا تنبيهُنا على أنّ القرب يُفهم على ما يليق به سبحانه، فتحرّزٌ منّا؛ ولم يبسط السعديُّ الكلام في ذلك في هذا الموضع، ومظانُّه كتبُ الاعتقاد.**\n**والإحالةُ إلى الروم ٢٢ هي إلى ما تقدّم في موضعها، بنصّ صاحبه هناك.**"}},{"n":17,"reflection":{"text":"«إذ يتلقى المتلقيان عن اليمين وعن الشمال قعيد»: حين يتلقّى الملكانِ الكاتبانِ عن اليمينِ وعن الشمالِ قاعدان يكتبان؛ ففي هذا بيانُ كتابةِ الملكين للأعمال؛ فاستحضر أنّ ملكين يكتبان كلَّ عملك، فراقب قولك وعملك، فما من عملٍ إلا وهو مكتوبٌ عليك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ كتابةِ الملكين، ومراقبةُ القولِ والعمل."},"action":{"text":"تأمّل كتابةَ الملكين: اذكر حين يتلقّى ويأخذ الملكانِ الموكّلانِ بالإنسانِ ما يصدر منه: أحدهما عن يمينه يكتب الحسنات، والآخرُ عن شماله يكتب السيّئات؛ قعيدٌ ملازمٌ قاعدٌ لا يفارقه «إذ يتلقى المتلقيان عن اليمين وعن الشمال قعيد»؛ ففي هذا بيانُ أنّ ملكين موكّلين بالإنسانِ يكتبان أعماله وأقواله؛ فعن يمينه ملكٌ يكتب الحسنات، وعن شماله ملكٌ يكتب السيّئات؛ فاستحضر أنت أنّ ملكين يكتبان كلَّ ما تقول وتعمل؛ فراقب قولك وعملك وحركاتك؛ وإنّ عليكم لحافظين، كرامًا كاتبين، يعلمون ما تفعلون؛ فما من عملٍ أو قولٍ إلا وهو مكتوبٌ عليك في صحيفتك؛ فمن استحضر كتابةَ الملكين راقب أعماله وأقواله، ومن غفل عنها تساهل؛ فاجعل استحضارَ كتابةِ الملكين ومراقبةَ قولك وعملك دأبك؛ فبمراقبتهما تحفظ لسانك وجوارحك عن المعاصي."}},{"n":18,"reflection":{"text":"«ما يلفظ من قول إلا لديه رقيب عتيد»: ما ينطق الإنسانُ بكلمةٍ إلا وعنده ملكٌ رقيبٌ حاضرٌ يكتبها؛ ففي هذا تأكيدُ كتابةِ الأقوال؛ فاحفظ لسانك، فكلُّ كلمةٍ تقولها مكتوبة، فتكلّم بخيرٍ أو اصمت، فاللسانُ يُكتَب عليه كلُّ لفظة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ اللسانِ عن كلِّ لفظةٍ سيّئة، وإدراكُ أنها مكتوبة."},"action":{"text":"تأمّل تأكيدَ كتابةِ الأقوال: ما يلفظ الإنسانُ وينطق من قولٍ خيرٍ أو شرٍّ، إلا وعنده رقيبٌ حاضرٌ عتيدٌ مُعَدٌّ لكتابةِ ما يقول، لا يفوته شيء «ما يلفظ من قول إلا لديه رقيب عتيد»؛ ففي هذا تأكيدُ أنّ كلَّ كلمةٍ ينطق بها الإنسانُ تُكتَب عليه؛ فلا يفلت من الكتابةِ لفظٌ واحد؛ فاحفظ أنت لسانك، فكلُّ كلمةٍ تقولها مكتوبةٌ عليك محفوظة؛ فتكلّم بالخيرِ أو اصمت؛ من كان يؤمن بالله واليومِ الآخرِ فليقل خيرًا أو ليصمت؛ إنّ العبدَ ليتكلّم بالكلمةِ من رضوانِ الله لا يلقي لها بالًا يرفعه الله بها درجات، وإنّ العبدَ ليتكلّم بالكلمةِ من سخطِ الله لا يلقي لها بالًا يهوي بها في جهنّم؛ وهل يكبُّ الناسَ في النارِ على وجوههم إلا حصائدُ ألسنتهم؛ فمن حفظ لسانه عن السوءِ سلم، ومن أطلقه هلك؛ فاجعل حفظَ لسانك عن كلِّ لفظةٍ سيّئة، واستحضارَ كتابتها، دأبك؛ فبحفظِ اللسانِ تسلم من كثيرٍ من الآثام."}},{"n":19,"reflection":{"text":"«وجاءت سكرة الموت بالحق ذلك ما كنت منه تحيد»، وجاءت شدّةُ الموتِ وغمرتُه بالحقِّ الذي لا مفرَّ منه، ذلك ما كنت منه تفرُّ وتهرب؛ ففي هذا بيانُ حتميّةِ الموتِ وشدّته؛ فاستعدّ للموتِ الذي لا مفرَّ منه، فالموتُ حقٌّ آتٍ، فبادر بالعملِ قبل أن تفاجئك سكرتُه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للموتِ الذي لا مفرَّ منه، والمبادرةُ بالعمل."},"action":{"text":"تأمّل حتميّةَ الموتِ وشدّته: وجاءت سكرةُ الموتِ وشدّته وغمرتُه بالحقِّ والأمرِ الذي لا شكَّ فيه ولا مفرَّ منه؛ ذلك الموتُ ما كنت، أيها الإنسانُ، منه تحيد وتفرُّ وتهرب، فقد أدركك «وجاءت سكرة الموت بالحق ذلك ما كنت منه تحيد»؛ ففي هذا بيانُ حتميّةِ الموتِ وشدّةِ سكرته، وأنه حقٌّ لا مفرَّ منه؛ فتأتي سكرةُ الموتِ فتغلب الإنسانَ ولو كان يفرُّ منها؛ فاستعدّ أنت للموتِ الذي لا مفرَّ منه؛ كلُّ نفسٍ ذائقةُ الموت؛ أينما تكونوا يدرككم الموتُ ولو كنتم في بروجٍ مشيّدة؛ قل إنّ الموتَ الذي تفرّون منه فإنه ملاقيكم؛ فالموتُ حقٌّ آتٍ لا محالة؛ فبادر بالعملِ الصالحِ والتوبةِ قبل أن تفاجئك سكرةُ الموت؛ وأنفقوا من ما رزقناكم من قبلِ أن يأتيَ أحدكم الموت؛ فمن استعدّ للموتِ بالعملِ نجا، ومن غفل عنه وسوّف خسر؛ فاجعل الاستعدادَ للموتِ بالعملِ الصالحِ والتوبةِ دأبك؛ فبالاستعدادِ للموتِ تنجو حين تأتيك سكرته."}},{"n":20,"reflection":{"text":"«ونفخ في الصور ذلك يوم الوعيد»، ونُفِخ في الصورِ للبعث، ذلك يومُ الوعيدِ الذي وُعِد به المكذّبون؛ ففي هذا بيانُ يومِ البعثِ والوعيد؛ فاستعدّ ليومِ الوعيدِ الذي يُنفَخ فيه في الصور، فالبعثُ حقٌّ، فاعمل ليومِ الوعيدِ قبل مجيئه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ الوعيدِ والبعث، والعملُ له."},"action":{"text":"تأمّل يومَ البعثِ والوعيد: ونُفِخ في الصورِ النفخةُ الثانيةُ للبعثِ والنشور، فيقوم الناسُ من قبورهم؛ ذلك اليومُ هو يومُ الوعيدِ الذي وُعِد به المكذّبون من العذابِ والحساب «ونفخ في الصور ذلك يوم الوعيد»؛ ففي هذا بيانُ أنّ النفخَ في الصورِ إيذانٌ بيومِ البعثِ والوعيد؛ فإذا نُفِخ في الصورِ قام الناسُ للحسابِ والجزاء؛ فاستعدّ أنت ليومِ الوعيدِ الذي يُنفَخ فيه في الصور؛ ونُفِخ في الصورِ فصعق من في السماواتِ ومن في الأرضِ إلا من شاء الله ثم نُفِخ فيه أخرى فإذا هم قيامٌ ينظرون؛ يومَ يُنفَخ في الصورِ فتأتون أفواجًا؛ فالبعثُ حقٌّ لا ريب فيه؛ فاعمل ليومِ الوعيدِ والحسابِ قبل مجيئه؛ فمن استعدّ ليومِ الوعيدِ بالعملِ نجا، ومن غفل عنه خسر؛ فاجعل الاستعدادَ ليومِ الوعيدِ والبعثِ بالعملِ الصالحِ دأبك."}},{"n":21,"reflection":{"text":"«وجاءت كل نفس معها سائق وشهيد»، وجاءت كلُّ نفسٍ يومَ القيامةِ معها ملكٌ يسوقها إلى المحشرِ وملكٌ يشهد عليها بعملها؛ ففي هذا بيانُ حالِ النفوسِ يومَ الحشر؛ فاستعدّ لذلك اليومِ الذي تُساق فيه وتُشهَد عليك، فاعمل صالحًا يشهد لك، فكلُّ نفسٍ محاسبةٌ مشهودٌ عليها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ الحشر، والعملُ الصالحُ ليشهد للنفس."},"action":{"text":"تأمّل حالَ النفوسِ يومَ الحشر: وجاءت كلُّ نفسٍ، برّةٍ أو فاجرة، يومَ القيامةِ إلى المحشر، معها سائقٌ من الملائكةِ يسوقها ويحضرها للحساب، وشهيدٌ من الملائكةِ يشهد عليها بما عملت؛ أو تشهد عليها جوارحها «وجاءت كل نفس معها سائق وشهيد»؛ ففي هذا بيانُ أنّ كلَّ نفسٍ تُساق يومَ القيامةِ إلى الموقفِ ويُشهَد عليها بعملها؛ فلكلِّ نفسٍ سائقٌ يسوقها وشاهدٌ يشهد عليها؛ فاستعدّ أنت لذلك اليومِ الذي تُساق فيه إلى الحسابِ ويُشهَد عليك؛ يومَ تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون؛ وأشرقت الأرضُ بنورِ ربّها ووُضِع الكتابُ وجيء بالنبيّين والشهداء؛ فاعمل عملًا صالحًا يشهد لك لا عليك؛ فمن عمل صالحًا شهدت له جوارحه وملائكته، ومن أساء شهدت عليه؛ فاجعل الاستعدادَ ليومِ الحشرِ بالعملِ الصالحِ الذي يشهد لك دأبك."}},{"n":22,"reflection":{"text":"«لقد كنت في غفلة من هذا فكشفنا عنك غطاءك فبصرك اليوم حديد»: يُقال للإنسان: لقد كنت في غفلةٍ من هذا اليوم، فكشفنا عنك غطاءك، فبصرك اليومَ حادٌّ قويّ؛ ففي هذا بيانُ زوالِ الغفلةِ يومَ القيامة؛ فاستيقظ من غفلتك في الدنيا قبل أن يُكشَف الغطاءُ في الآخرة، فالغفلةُ تزول يومَ القيامةِ حيث لا ينفع، فأزلها الآن بالتذكّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستيقاظُ من الغفلةِ في الدنيا قبل كشفِ الغطاءِ في الآخرة."},"action":{"text":"تأمّل زوالَ الغفلةِ يومَ القيامة: يُقال للإنسانِ يومَ القيامةِ حين يعاين الحقائق: لقد كنت في الدنيا في غفلةٍ عن هذا اليومِ وأهواله، لاهيًا عنه؛ فكشفنا عنك غطاءك الذي كان يحجبك عن الحقِّ من الغفلةِ والهوى؛ فبصرك اليومَ حديدٌ حادٌّ قويٌّ ترى به ما كنت تنكره «لقد كنت في غفلة من هذا فكشفنا عنك غطاءك فبصرك اليوم حديد»؛ ففي هذا بيانُ أنّ الإنسانَ كان في الدنيا غافلًا، فإذا كان يومُ القيامةِ زالت غفلته وأبصر الحقائق، حيث لا ينفعه ذلك؛ فيرى ما كان يُكذّب به عيانًا؛ فاستيقظ أنت من غفلتك في الدنيا قبل أن يُكشَف الغطاءُ في الآخرة؛ فالغفلةُ تزول يومَ القيامةِ حيث لا ينفع الإبصار؛ اقترب للناسِ حسابهم وهم في غفلةٍ معرضون؛ فأزل غفلتك الآن بالتذكّرِ والتدبّرِ والعملِ للآخرة؛ فمن أزال غفلته في الدنيا واستعدّ نجا، ومن بقي غافلًا حتى كُشِف الغطاءُ ندم؛ فاجعل الاستيقاظَ من الغفلةِ بالتذكّرِ والعملِ دأبك؛ فبإزالةِ الغفلةِ في الدنيا تستعدّ ليومِ القيامة."}}]},{"title":"مشهدُ الحساب: السائقُ والشهيد، وجزاءُ الكافرِ العنيد","range":[23,29],"theme":"إحضارُ القرينِ صحيفةَ العمل، والأمرُ بإلقاءِ كلِّ كفّارٍ عنيدٍ منّاعٍ للخيرِ معتدٍ مريبٍ مشركٍ في العذابِ الشديد، وتبرّؤِ الشيطانِ منه، وأنّ الله قدّم الوعيدَ فلا خصومة، ولا يُبدَّل القولُ لديه وما هو بظلّامٍ للعبيد","verses":[{"n":23,"reflection":{"text":"«وقال قرينه هذا ما لدي عتيد»، وقال قرينه من الملائكةِ الموكّلِ به: هذا ما عندي من عمله حاضرٌ مُعَدّ؛ ففي هذا بيانُ حضورِ صحيفةِ العمل؛ فاعلم أنّ عملك حاضرٌ مُعَدٌّ يومَ القيامة، فأعدَّ لصحيفتك ما يسرّك، فما تعمله محفوظٌ حاضر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعدادُ العملِ الصالحِ للصحيفة، وإدراكُ حضورِ العمل."},"action":{"text":"تأمّل حضورَ صحيفةِ العمل: وقال قرينه، وهو الملكُ الموكّلُ به الكاتبُ لعمله: هذا الذي عندي من عمله وكتابِ سيّئاته وحسناته حاضرٌ عتيدٌ مُعَدٌّ مهيّأٌ لا نقصَ فيه ولا زيادة «وقال قرينه هذا ما لدي عتيد»؛ ففي هذا بيانُ أنّ الملكَ الموكّلَ يُحضِر صحيفةَ عملِ الإنسانِ يومَ القيامةِ حاضرةً معدّة؛ فما عمله محفوظٌ حاضرٌ لا يضيع منه شيء؛ فاعلم أنت أنّ عملك كلَّه حاضرٌ مُعَدٌّ يومَ القيامةِ في صحيفتك؛ ووُضِع الكتابُ فترى المجرمين مشفقين ممّا فيه ويقولون يا ويلتنا ما لهذا الكتابِ لا يغادر صغيرةً ولا كبيرةً إلا أحصاها؛ ووجدوا ما عملوا حاضرًا؛ فأعدَّ لصحيفتك ما يسرّك من العملِ الصالح؛ فما تعمله في الدنيا محفوظٌ حاضرٌ يومَ القيامة؛ فمن أعدَّ عملًا صالحًا سُرّ به، ومن أعدَّ سوءًا ساءه؛ فاجعل إعدادَ العملِ الصالحِ لصحيفتك دأبك؛ فبالعملِ الصالحِ تُسِرّك صحيفتك يومَ العرض."}},{"n":24,"reflection":{"text":"«ألقيا في جهنم كل كفار عنيد»: يُقال للملكين: ألقيا في جهنّمَ كلَّ شديدِ الكفرِ معاندٍ للحق؛ ففي هذا بيانُ جزاءِ الكافرِ العنيد؛ فاحذر الكفرَ والعنادَ اللذين يورثان النار، فآمن واقبل الحقَّ ولا تعاند، فالكفرُ والعنادُ سببُ الإلقاءِ في جهنّم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ وتركُ العناد، والحذرُ من الكفرِ الموجبِ للنار."},"action":{"text":"تأمّل جزاءَ الكافرِ العنيد: يُقال للملكين السائقِ والشهيد: ألقيا في نارِ جهنّمَ كلَّ كفّارٍ شديدِ الكفرِ والجحود، عنيدٍ معاندٍ للحقِّ مجانبٍ له، لا يقبله ولا يذعن له «ألقيا في جهنم كل كفار عنيد»؛ ففي هذا بيانُ أنّ الكافرَ العنيدَ المعاندَ للحقِّ يُلقى في جهنّم؛ فالكفرُ والعنادُ سببُ الإلقاءِ في النار؛ فاحذر أنت الكفرَ الشديدَ والعنادَ ومجانبةَ الحق؛ فآمن بالله واقبل الحقَّ ولا تعاند؛ فالعنادُ ومجانبةُ الحقِّ من صفاتِ أهلِ النار؛ ويجادلون بالباطلِ ليدحضوا به الحق؛ ثم أصرَّ مستكبرًا كأن لم يسمعها؛ فمن قبل الحقَّ وأذعن له نجا، ومن كفر وعاند أُلقِي في جهنّم؛ فاجعل قبولَ الحقِّ والإذعانَ له وتركَ العنادِ دأبك؛ فبقبولِ الحقِّ تنجو من نارِ العنيدين."}},{"n":25,"reflection":{"text":"«مناع للخير معتد مريب»: منّاعٍ للخيرِ (كالزكاةِ والحقوق)، معتدٍ على الحدود، مريبٍ شاكٍّ في الحق؛ ففي هذا بيانُ صفاتِ أهلِ النار؛ فاحذر منعَ الخيرِ والاعتداءَ والشكّ، فكن باذلًا للخيرِ ملتزمًا للحدودِ موقنًا بالحق، فهذه صفاتُ الناجين لا الهالكين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ الخيرِ والتزامُ الحدودِ واليقينُ بالحق، وتركُ صفاتِ أهلِ النار."},"action":{"text":"تأمّل صفاتِ أهلِ النار: هذا الكفّارُ العنيدُ منّاعٌ للخيرِ الذي عليه من الزكاةِ والصدقةِ والحقوقِ والطاعات، يمنعها ويبخل بها؛ معتدٍ متجاوزٍ للحدودِ ظالمٍ في معاملته؛ مريبٍ شاكٍّ في الله ودينه، مُوقِعٍ غيره في الريب «مناع للخير معتد مريب»؛ ففي هذا بيانُ صفاتٍ ثلاثٍ لأهلِ النار: منعُ الخير، والاعتداء، والشكُّ في الحق؛ فهؤلاء الصفاتُ توجب النار؛ فاحذر أنت منعَ الخيرِ والحقوقِ الواجبةِ عليك؛ واحذر الاعتداءَ على حدودِ الله وحقوقِ العباد؛ واحذر الشكَّ والريبَ في الحق؛ ويلٌ لكلِّ همزةٍ لمزة، الذي جمع مالًا وعدّده؛ والذين في أموالهم حقٌّ معلومٌ للسائلِ والمحروم؛ فكن أنت باذلًا للخيرِ والحقوق، ملتزمًا لحدودِ الله، موقنًا بالحقِّ لا شاكًّا فيه؛ فهذه صفاتُ الناجين؛ فمن اتّصف بالبذلِ والالتزامِ واليقينِ نجا، ومن اتّصف بالمنعِ والاعتداءِ والشكِّ هلك؛ فاجعل بذلَ الخيرِ والتزامَ الحدودِ واليقينَ بالحقِّ دأبك."}},{"n":26,"reflection":{"text":"«الذي جعل مع الله إلها آخر فألقياه في العذاب الشديد»: الذي جعل مع الله معبودًا آخرَ (أشرك)، فألقياه في العذابِ الشديد؛ ففي هذا بيانُ أنّ الشركَ أعظمُ أسبابِ العذاب؛ فوحّد الله ولا تشرك به، فالشركُ يورث العذابَ الشديد، فاحذره واجعل عبادتك خالصةً لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله وإخلاصُ العبادة، والحذرُ من الشركِ الموجبِ للعذاب."},"action":{"text":"تأمّل أنّ الشركَ سببُ العذاب: هذا الكفّارُ هو الذي جعل مع الله معبودًا آخرَ يعبده ويدعوه، فأشرك بالله؛ فألقياه، أيها الملكان، في العذابِ الشديدِ في جهنّم جزاءَ شركه «الذي جعل مع الله إلها آخر فألقياه في العذاب الشديد»؛ ففي هذا بيانُ أنّ الشركَ بالله من أعظمِ أسبابِ العذابِ الشديد؛ فمن جعل مع الله إلهًا آخرَ استحقّ العذابَ؛ فوحّد أنت الله وأخلص له العبادة، ولا تشرك به شيئًا؛ فالشركُ أعظمُ الذنوبِ وأشدُّها عقوبة؛ إنّ الله لا يغفر أن يُشرَك به ويغفر ما دون ذلك لمن يشاء؛ إنه من يشرك بالله فقد حرّم الله عليه الجنّةَ ومأواه النار؛ إنّ الشركَ لظلمٌ عظيم؛ فاحذر الشركَ جليّه وخفيّه؛ واجعل عبادتك ودعاءك وخوفك ورجاءك وتوكّلك لله وحده؛ فمن وحّد الله ونجا من الشركِ نجا من العذاب، ومن أشرك أُلقِي في العذابِ الشديد؛ فاجعل توحيدَ الله وإخلاصَ العبادةِ له دأبك."}},{"n":27,"reflection":{"text":"«قال قرينه ربنا ما أطغيته ولكن كان في ضلال بعيد»: قال قرينه من الشيطان: ربّنا ما أطغيته ولكن كان في ضلالٍ بعيدٍ باختياره؛ ففي هذا تبرّؤُ الشيطانِ من متّبعه؛ فاحذر اتّباعَ الشيطانِ فإنه يتبرّأ منك يومَ القيامة، فلا تجعله قرينك، فالشيطانُ يزيّن ثم يتبرّأ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّباعِ الشيطان، وإدراكُ أنه يتبرّأ من متّبعه."},"action":{"text":"تأمّل تبرّؤَ الشيطان: قال قرينه، وهو الشيطانُ الذي كان معه في الدنيا يزيّن له الكفرَ والمعاصي: ربّنا ما أطغيته ولا أكرهته على الكفر، ولكن كان هو في نفسه في ضلالٍ بعيدٍ عن الحق، فاختار الضلالَ بنفسه، وأنا دعوته فاستجاب «قال قرينه ربنا ما أطغيته ولكن كان في ضلال بعيد»؛ ففي هذا بيانُ تبرّؤِ الشيطانِ من متّبعه يومَ القيامة؛ فبعد أن أضلّه في الدنيا، يتبرّأ منه في الآخرة؛ فاحذر أنت اتّباعَ الشيطانِ وطاعته وتزيينه؛ فإنه يتبرّأ منك يومَ القيامة ويتخلّى عنك؛ وقال الشيطانُ لمّا قُضِي الأمرُ إنّ الله وعدكم وعدَ الحقِّ ووعدتكم فأخلفتكم... فلا تلوموني ولوموا أنفسكم؛ إنّ الشيطانَ لكم عدوٌّ فاتّخذوه عدوًّا؛ فلا تجعل الشيطانَ قرينك وقائدك؛ فالشيطانُ يزيّن الباطلَ ثم يتبرّأ من صاحبه؛ فمن عادى الشيطانَ ولم يتّبعه نجا، ومن اتّبعه أضلّه ثم تبرّأ منه؛ فاجعل الحذرَ من الشيطانِ وعداوتَه وتركَ اتّباعه دأبك."}},{"n":28,"reflection":{"text":"«قال لا تختصموا لدي وقد قدمت إليكم بالوعيد»: قال الله: لا تختصموا عندي وقد قدّمت إليكم بالوعيدِ على ألسنةِ الرسل؛ ففي هذا بيانُ أنّ الحجّةَ قامت بالوعيدِ المتقدّم؛ فاعلم أنّ الله أقام الحجّةَ بالرسلِ والوعيد، فلا عذرَ لك، فاستعدّ للوعيدِ الذي قُدِّم إليك بالإيمانِ والعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للوعيدِ المتقدّم، وإدراكُ قيامِ الحجّةِ بالرسل."},"action":{"text":"تأمّل قيامَ الحجّةِ بالوعيد: قال الله للمتخاصمين (الكافرِ وقرينه): لا تختصموا لديّ الآن، فالخصومةُ لا تنفع؛ وقد قدّمت إليكم في الدنيا بالوعيدِ والإنذارِ على ألسنةِ الرسلِ وفي الكتب، فأعذرت إليكم وأقمت الحجّة «قال لا تختصموا لدي وقد قدمت إليكم بالوعيد»؛ ففي هذا بيانُ أنّ الله أقام الحجّةَ على العبادِ بالوعيدِ المتقدّمِ على ألسنةِ الرسل، فلا عذرَ لهم؛ فالخصومةُ يومَ القيامةِ لا تنفع بعد قيامِ الحجّة؛ فاعلم أنت أنّ الله أقام الحجّةَ عليك بالرسلِ والكتبِ والوعيد؛ رسلًا مبشّرين ومنذرين لئلا يكون للناسِ على الله حجّةٌ بعد الرسل؛ وما كنّا معذّبين حتى نبعث رسولًا؛ فلا عذرَ لك بعد بلوغِ الوعيد؛ فاستعدّ للوعيدِ الذي قُدِّم إليك بالإيمانِ والعملِ الصالح؛ فمن استعدّ للوعيدِ المتقدّمِ بالعملِ نجا، ومن أعرض عنه هلك؛ فاجعل الاستعدادَ للوعيدِ الذي بلغك بالإيمانِ والعملِ دأبك."}},{"n":29,"reflection":{"text":"«ما يبدل القول لدي وما أنا بظلام للعبيد»: لا يُبدَّل القولُ عندي (فوعيدي نافذ)، وما أنا بظالمٍ للعبيد؛ ففي هذا بيانُ نفوذِ وعدِ الله وعدله؛ فاعلم أنّ وعدَ الله ووعيده نافذٌ لا يتبدّل، وأنّ الله لا يظلم أحدًا، فاطمئن لعدلِ الله، واعمل فإنّ الجزاءَ بالعدل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ لعدلِ الله ونفوذِ وعده، والعملُ لعدلِ الجزاء."},"action":{"text":"تأمّل نفوذَ وعدِ الله وعدله: ما يُبدَّل ويُغيَّر القولُ لديّ، فما حكمت به وأوعدت به نافذٌ لا يتبدّل ولا يُخلَف؛ وما أنا بظلّامٍ للعبيد، فلا أعذّب أحدًا بغيرِ ذنب، ولا أنقص من حسناته، ولا أزيد في سيّئاته «ما يبدل القول لدي وما أنا بظلام للعبيد»؛ ففي هذا بيانُ أنّ وعدَ الله ووعيده نافذٌ لا يتبدّل، وأنّ الله لا يظلم أحدًا من عباده؛ فحكمه عدلٌ ووعيده حقّ؛ فاعلم أنت أنّ وعدَ الله ووعيده نافذٌ لا يتبدّل ولا يُخلَف؛ إنّ الله لا يخلف الميعاد؛ وأنّ الله لا يظلم أحدًا مثقالَ ذرّة؛ إنّ الله لا يظلم الناسَ شيئًا؛ ومن يعمل مثقالَ ذرّةٍ خيرًا يره ومن يعمل مثقالَ ذرّةٍ شرًّا يره؛ فاطمئن لعدلِ الله في حكمه وجزائه؛ ولا تخف ظلمًا ولا هضمًا؛ واعمل صالحًا فإنّ الجزاءَ بالعدلِ التام؛ فمن اطمأنّ لعدلِ الله وعمل صالحًا فاز، ومن ظنّ بالله الظلمَ أساء؛ فاجعل الطمأنينةَ لعدلِ الله ونفوذِ وعده، والعملَ الصالحَ، دأبك."}}]},{"title":"جهنمُ والجنّة: صفاتُ أهلِ الجنّةِ ونعيمهم","range":[30,35],"theme":"سؤالُ جهنّمَ هل امتلأت وطلبُها المزيد، وإزلافُ الجنّةِ للمتّقين قريبةً، وأنها لكلِّ أوّابٍ حفيظٍ خشي الرحمنَ بالغيبِ وجاء بقلبٍ منيب، فيُقال ادخلوها بسلامٍ ذلك يومُ الخلود، لهم ما يشاؤون فيها ولدينا مزيد","verses":[{"n":30,"reflection":{"text":"«يوم نقول لجهنم هل امتلأت وتقول هل من مزيد»: يومَ نقول لجهنّم: هل امتلأتِ؟ وتقول: هل من مزيدٍ من الكفّار؟ ففي هذا بيانُ سعةِ جهنّمَ وكثرةِ أهلها؛ فاحذر أن تكون من أهلِ جهنّمَ التي تطلب المزيد، فاعمل لتنجو منها، فجهنّمُ واسعةٌ تطلب المزيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنجاةِ من جهنّم، وإدراكُ سعتها وكثرةِ أهلها."},"action":{"text":"تأمّل سعةَ جهنّم: اذكر يومَ نقول لجهنّمَ توبيخًا لأهلها: هل امتلأتِ بمن أُلقِي فيك؟ فتقول جهنّم: هل من مزيدٍ من الكفّارِ والعصاة؟ استزادةً لسعتها، أو استفهامًا: هل بقي أحد؟ حتى يضع الجبّارُ فيها قدمه فتقول قط قط «يوم نقول لجهنم هل امتلأت وتقول هل من مزيد»؛ ففي هذا بيانُ سعةِ جهنّمَ العظيمةِ وكثرةِ من يُلقى فيها؛ فهي تطلب المزيدَ من الكفّارِ لسعتها؛ فاحذر أنت أن تكون من أهلِ جهنّمَ التي تطلب المزيد؛ فاعمل عملًا صالحًا لتنجو منها؛ فجهنّمُ واسعةٌ عميقةٌ لا تمتلئ حتى يضع الله فيها قدمه؛ لأملأنّ جهنّمَ من الجِنّةِ والناسِ أجمعين؛ يوم يُدَعّون إلى نارِ جهنّمَ دعًّا؛ فبادر بالإيمانِ والعملِ الصالحِ لتنجو من النار؛ فمن عمل للنجاةِ من النارِ نجا منها، ومن أهملها وقع فيها؛ فاجعل العملَ للنجاةِ من جهنّمَ بالإيمانِ والتقوى دأبك."}},{"n":31,"reflection":{"text":"«وأزلفت الجنة للمتقين غير بعيد»، وقُرِّبت الجنّةُ للمتّقين قريبةً غيرَ بعيدة؛ ففي هذا بيانُ قربِ الجنّةِ للمتّقين؛ فاطلب الجنّةَ القريبةَ بالتقوى، فالجنّةُ قريبةٌ من أهلِ التقوى، فاعمل بالتقوى لتنالها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الجنّةِ القريبةِ بالتقوى، والعملُ لها."},"action":{"text":"تأمّل قربَ الجنّةِ للمتّقين: وأُزلِفت وقُرِّبت الجنّةُ للمتّقين، حالَ كونها غيرَ بعيدةٍ عنهم، بل قريبةً منهم يرونها ويطمئنّون إليها؛ فبعد أن ذكر النارَ وأهلها، ذكر الجنّةَ وأهلها مقابلةً وترغيبًا «وأزلفت الجنة للمتقين غير بعيد»؛ ففي هذا بيانُ أنّ الجنّةَ قُرِّبت للمتّقين قريبةً غيرَ بعيدة؛ فهي معدّةٌ لهم قريبةٌ منهم؛ فاطلب أنت الجنّةَ القريبةَ بالتقوى، فعلِ المأموراتِ وتركِ المحظورات؛ فالجنّةُ قريبةٌ من أهلِ التقوى؛ وأزلفتِ الجنّةُ للمتّقين غيرَ بعيد؛ وسارعوا إلى مغفرةٍ من ربّكم وجنّةٍ عرضها السماواتُ والأرضُ أُعِدّت للمتّقين؛ فاعمل بالتقوى لتنال الجنّةَ القريبة؛ فمن اتّقى نال الجنّةَ القريبة، ومن فرّط أُبعِد عنها؛ فاجعل التقوى سبيلك لتقريبِ الجنّةِ منك؛ فبالتقوى تُزلَف لك الجنّةُ وتقرب."}},{"n":32,"reflection":{"text":"«هذا ما توعدون لكل أواب حفيظ»: هذا ما توعدون به من الجنّة، لكلِّ رجّاعٍ إلى الله حافظٍ لحدوده؛ ففي هذا بيانُ صفاتِ أهلِ الجنّة؛ فكن أوّابًا رجّاعًا إلى الله، حافظًا لحدوده وأوامره، فهاتان صفتان توصلان للجنّة، فاجعلهما دأبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأوبةُ إلى الله وحفظُ حدوده، لنيلِ الجنّة."},"action":{"text":"تأمّل صفاتِ أهلِ الجنّة: يُقال للمتّقين: هذا الذي ترونه من نعيمِ الجنّةِ هو ما كنتم توعدون به في الدنيا؛ وهو معدٌّ لكلِّ أوّابٍ رجّاعٍ إلى الله بالتوبةِ والطاعةِ والإقبالِ عليه، حفيظٍ حافظٍ لحدودِ الله وأوامره ونواهيه وحقوقه «هذا ما توعدون لكل أواب حفيظ»؛ ففي هذا بيانُ صفتين من صفاتِ أهلِ الجنّة: الأوبةُ (الرجوعُ إلى الله)، والحفظُ (لحدودِ الله)؛ فبهاتين الصفتين يُنال الوعدُ بالجنّة؛ فكن أنت أوّابًا رجّاعًا إلى الله كثيرَ التوبةِ والإنابةِ والذكر؛ فنِعم العبدُ إنه أوّاب؛ إنه كان للأوّابين غفورًا؛ وكن حفيظًا حافظًا لحدودِ الله وأوامره وحقوقه وجوارحك ونفسك؛ والحافظون لحدودِ الله؛ حافظوا على الصلوات؛ فمن كان أوّابًا حفيظًا نال الجنّة؛ فاجعل الأوبةَ إلى الله وحفظَ حدوده دأبك؛ فبالأوبةِ والحفظِ تُنال الجنّةُ الموعودة."}},{"n":33,"reflection":{"text":"«من خشي الرحمن بالغيب وجاء بقلب منيب»: من خشي الرحمنَ في غيبته حيث لا يراه أحد، وجاء ربه بقلبٍ منيبٍ رجّاعٍ مقبل؛ ففي هذا بيانُ تمامِ صفاتِ أهلِ الجنّة؛ فاخشَ الله في السرِّ والعلن، وأقبل عليه بقلبٍ منيب، فخشيةُ الله بالغيبِ والقلبُ المنيبُ من أعظمِ صفاتِ الفائزين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"خشيةُ الله بالغيب، والإقبالُ عليه بقلبٍ منيب."},"action":{"text":"تأمّل تمامَ صفاتِ أهلِ الجنّة: هذا الوعدُ لمن خشي الرحمنَ بالغيبِ، أي في سرّه وخلوته حيث لا يراه إلا الله، أو خشيه وهو لم يره ،؛ وجاء ربه يومَ القيامةِ بقلبٍ منيبٍ رجّاعٍ إلى الله، مقبلٍ عليه، سليمٍ من الشركِ والشكِّ والمعاصي «من خشي الرحمن بالغيب وجاء بقلب منيب»؛ ففي هذا بيانُ تمامِ صفاتِ أهلِ الجنّة: خشيةُ الله بالغيب، والإتيانُ بقلبٍ منيب؛ فبهما يُنال نعيمُ الجنّة؛ فاخشَ أنت الله في السرِّ والعلن، حيث يراك وحيث لا يراك الناس؛ إنّ الذين يخشون ربّهم بالغيبِ لهم مغفرةٌ وأجرٌ كبير؛ ومن خاف مقامَ ربّه جنّتان؛ وأقبل على الله بقلبٍ منيبٍ سليمٍ رجّاعٍ إليه؛ إلا من أتى الله بقلبٍ سليم؛ يومَ لا ينفع مالٌ ولا بنون إلا من أتى الله بقلبٍ سليم؛ فخشيةُ الله بالغيبِ والقلبُ المنيبُ السليمُ من أعظمِ صفاتِ الفائزين؛ فمن خشي الله بالغيبِ وأناب إليه فاز، ومن غفل وأعرض خسر؛ فاجعل خشيةَ الله بالغيبِ والإنابةَ إليه بقلبٍ سليمٍ دأبك."}},{"n":34,"reflection":{"text":"«ادخلوها بسلام ذلك يوم الخلود»: يُقال لهم: ادخلوا الجنّةَ بسلامٍ آمنين، ذلك يومُ الخلودِ الذي لا موتَ بعده؛ ففي هذا بشارةُ أهلِ الجنّةِ بالدخولِ والخلود؛ فاعمل لتدخل الجنّةَ بسلامٍ وتخلد فيها، فالجنّةُ دارُ سلامٍ وخلود، فاعمل لها بالتقوى والإنابة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لدخولِ الجنّةِ بسلامٍ والخلودِ فيها."},"action":{"text":"تأمّل بشارةَ أهلِ الجنّة: يُقال للمتّقين عند دخولهم الجنّة: ادخلوها بسلامٍ، أي سالمين من كلِّ آفةٍ ومكروه، مسلَّمًا عليكم من الله وملائكته؛ ذلك اليومُ هو يومُ الخلودِ الذي لا انقطاعَ له ولا موتَ بعده «ادخلوها بسلام ذلك يوم الخلود»؛ ففي هذا بشارةُ أهلِ الجنّةِ بدخولها بسلامٍ وأمان، والخلودِ فيها أبدًا؛ فيدخلونها سالمين آمنين مسلَّمًا عليهم؛ ويخلدون فيها بلا موت؛ فاعمل أنت لتدخل الجنّةَ بسلامٍ وأمان، وتخلد فيها؛ والملائكةُ يدخلون عليهم من كلِّ بابٍ سلامٌ عليكم بما صبرتم؛ سلامٌ قولًا من ربٍّ رحيم؛ وسيق الذين اتّقوا ربّهم إلى الجنّةِ زمرًا... وقال لهم خزنتها سلامٌ عليكم طبتم فادخلوها خالدين؛ فالجنّةُ دارُ السلامِ والخلود؛ فاعمل لها بالتقوى والإنابةِ والخشية؛ فمن عمل للجنّةِ دخلها بسلامٍ وخلد فيها، ومن غفل حُرِمها؛ فاجعل العملَ لدخولِ الجنّةِ بسلامٍ والخلودِ فيها دأبك."}},{"n":35,"reflection":{"text":"«لهم ما يشاءون فيها ولدينا مزيد»: لهم في الجنّةِ ما يشاؤون ويشتهون، ولدينا مزيدٌ من النعيمِ فوق ما طلبوا (والنظرُ إلى وجهِ الله)؛ ففي هذا بيانُ كمالِ نعيمِ الجنّةِ والمزيد؛ فاطلب الجنّةَ التي فيها ما تشاء والمزيد، فنعيمُ الجنّةِ يفوق كلَّ ما تتمنّى، فاعمل لها لتنال المزيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للجنّةِ ونعيمها الذي يفوق الأمانيَّ، وطلبُ المزيد."},"action":{"text":"تأمّل كمالَ نعيمِ الجنّة: لأهلِ الجنّةِ فيها كلُّ ما يشاؤون ويتمنّون ويشتهون، لا يُمنَعون شيئًا طلبوه؛ ولدينا مزيدٌ من النعيمِ فوق ما طلبوا وتمنّوا، ممّا لم يخطر على قلوبهم؛ وأعظمه النظرُ إلى وجهِ الله الكريم «لهم ما يشاءون فيها ولدينا مزيد»؛ ففي هذا بيانُ كمالِ نعيمِ الجنّة: فيها ما تشتهيه الأنفس، ومزيدٌ فوق ذلك؛ فيُعطَون ما يشاؤون ويُزادون؛ فاطلب أنت الجنّةَ التي فيها ما تشاء والمزيد؛ ولكم فيها ما تشتهي أنفسكم ولكم فيها ما تدّعون؛ فيها ما تشتهيه الأنفسُ وتلذُّ الأعين؛ للذين أحسنوا الحسنى وزيادة (والزيادةُ النظرُ إلى وجهِ الله)؛ فنعيمُ الجنّةِ يفوق كلَّ ما تتمنّى وتتصوّر؛ أعددتُ لعبادي الصالحين ما لا عينٌ رأت ولا أذنٌ سمعت ولا خطر على قلبِ بشر؛ فاعمل للجنّةِ لتنال ما تشاء والمزيد؛ فمن عمل للجنّةِ نال نعيمها والمزيد، ومن غفل حُرِم؛ فاجعل العملَ للجنّةِ ونعيمها الذي يفوق الأمانيَّ دأبك."}}]},{"title":"الاعتبارُ بالأقوياء، وشرطُ الذكرى، وكمالُ القدرة","range":[36,38],"theme":"التذكيرُ بإهلاكِ من هم أشدُّ بطشًا فلم يجدوا محيصًا، وأنّ في ذلك ذكرى لمن كان له قلبٌ أو ألقى السمعَ وهو شهيد، وأنّ الله خلق السماواتِ والأرضَ في ستّةِ أيامٍ وما مسّه من لغوبٍ فكيف يعجز عن البعث","verses":[{"n":36,"reflection":{"text":"«وكم أهلكنا قبلهم من قرن هم أشد منهم بطشا فنقبوا في البلاد هل من محيص»، وكم أهلكنا قبل هؤلاء من أممٍ هم أشدُّ منهم قوّةً وبطشًا، فطافوا وتنقّلوا في البلادِ فهل وجدوا مهربًا من الموتِ أو العذاب؟ ففي هذا التذكيرُ بإهلاكِ الأقوياءِ وأنه لا مهرب؛ فاعتبر بإهلاكِ الأقوياءِ قبلك، فلا مهربَ من الله، فاستعدّ للقائه ولا تغترّ بقوّتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بإهلاكِ الأقوياء، وإدراكُ أنه لا مهربَ من الله."},"action":{"text":"تأمّل التذكيرَ بإهلاكِ الأقوياء: وكم أهلكنا قبل هؤلاء المكذّبين من قريشٍ من أممٍ وقرونٍ كانوا أشدَّ منهم قوّةً وبطشًا وأموالًا؛ فنقّبوا وطافوا وتصرّفوا في البلادِ وجابوها بقوّتهم؛ فهل وجدوا محيصًا ومهربًا ومنجًى من الموتِ أو من عذابِ الله؟ لا «وكم أهلكنا قبلهم من قرن هم أشد منهم بطشا فنقبوا في البلاد هل من محيص»؛ ففي هذا التذكيرُ بإهلاكِ الأممِ القويّةِ قبل قريش، وأنّ قوّتهم لم تنفعهم ولم يجدوا مهربًا؛ فأهلكهم الله رغمَ قوّتهم؛ فاعتبر أنت بإهلاكِ الأقوياءِ الجبابرةِ قبلك؛ فقوّتهم لم تدفع عنهم عذابَ الله؛ فلا مهربَ ولا مفرَّ من الله وقضائه؛ أفلم يسيروا في الأرضِ فينظروا كيف كان عاقبةُ الذين من قبلهم، كانوا أشدَّ منهم قوّة؛ فأين المفرّ؛ فاستعدّ للقاءِ الله ولا تغترّ بقوّتك أو مالك أو جاهك؛ فمن اعتبر بإهلاكِ الأقوياءِ واستعدّ نجا، ومن اغترّ بقوّته هلك؛ فاجعل الاعتبارَ بإهلاكِ الأقوياءِ والاستعدادَ للقاءِ الله دأبك."}},{"n":37,"reflection":{"text":"«إن في ذلك لذكرى لمن كان له قلب أو ألقى السمع وهو شهيد»: إنّ في ذلك لعبرةً وتذكرةً لمن كان له قلبٌ واعٍ، أو أصغى السمعَ وهو حاضرُ القلب؛ ففي هذا بيانُ شرطِ الانتفاعِ بالعبرة: قلبٌ واعٍ وسمعٌ مصغٍ؛ فأحضر قلبك وأصغِ سمعك عند تلاوةِ القرآنِ والمواعظ، فالانتفاعُ بالذكرى يحتاج قلبًا حاضرًا وسمعًا واعيًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إحضارُ القلبِ وإصغاءُ السمعِ للانتفاعِ بالذكرى."},"action":{"text":"تأمّل شرطَ الانتفاعِ بالعبرة: إنّ في هذا الذي ذُكِر من إهلاكِ الأممِ وأدلّةِ البعثِ لعبرةً وتذكرةً عظيمة؛ لكن لمن كان له قلبٌ حيٌّ واعٍ يعقل ويتدبّر؛ أو ألقى السمعَ وأصغى بانتباهٍ إلى الحق، وهو شهيدٌ حاضرُ القلبِ ليس غافلًا «إن في ذلك لذكرى لمن كان له قلب أو ألقى السمع وهو شهيد»؛ ففي هذا بيانُ أنّ الانتفاعَ بالذكرى والعبرةِ يحتاج إلى قلبٍ واعٍ حاضر، وسمعٍ مصغٍ منتبه؛ فمن غفل قلبه أو لها سمعه لم ينتفع؛ فأحضر أنت قلبك وأصغِ سمعك عند تلاوةِ القرآنِ وسماعِ المواعظِ والعبر؛ فالانتفاعُ بالذكرى مشروطٌ بحضورِ القلبِ وإصغاءِ السمع؛ إنّ في ذلك لذكرى لأولي الألباب؛ فذكّر إن نفعتِ الذكرى؛ فمن أحضر قلبه وأصغى سمعه انتفع بالذكرى، ومن غفل قلبه ولها سمعه لم ينتفع؛ فاجعل إحضارَ قلبك وإصغاءَ سمعك عند القرآنِ والمواعظِ دأبك؛ فبحضورِ القلبِ وإصغاءِ السمعِ تنتفع بالذكرى والعبر."}},{"n":38,"reflection":{"text":"«ولقد خلقنا السماوات والأرض وما بينهما في ستة أيام وما مسنا من لغوب»، ولقد خلقنا السماواتِ والأرضَ وما بينهما في ستّةِ أيامٍ وما أصابنا من تعبٍ ولا إعياء؛ ففي هذا بيانُ كمالِ قدرةِ الله بلا تعب، وردٌّ على من زعم غيرَ ذلك؛ فاعلم أنّ الله لا يعجزه شيءٌ ولا يتعب، فالبعثُ يسيرٌ عليه، فأيقن بكمالِ قدرته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بكمالِ قدرةِ الله بلا تعب، وأنّ البعثَ يسيرٌ عليه."},"action":{"text":"تأمّل كمالَ قدرةِ الله: ولقد خلقنا السماواتِ السبعَ والأرضين وما بينهما من المخلوقاتِ العظيمةِ في ستّةِ أيام، وما مسّنا ولا أصابنا من لغوبٍ، أي تعبٍ ولا إعياءٍ ولا نصب «ولقد خلقنا السماوات والأرض وما بينهما في ستة أيام وما مسنا من لغوب»؛ ففي هذا بيانُ كمالِ قدرةِ الله، حيث خلق الكونَ العظيمَ بلا تعبٍ ولا إعياء؛ وردٌّ على اليهودِ الذين زعموا أنّ الله استراح يومَ السبت؛ فاعلم أنت أنّ الله لا يعجزه شيء، ولا يمسّه تعبٌ ولا إعياء؛ فمن خلق الكونَ العظيمَ بلا تعبٍ لا يعجز عن البعث؛ الله لا إله إلا هو الحيُّ القيّوم لا تأخذه سنةٌ ولا نوم؛ وسِع كرسيّه السماواتِ والأرضَ ولا يؤوده حفظهما؛ فالبعثُ يسيرٌ على الله القادرِ الذي لا يتعب؛ أفعيينا بالخلقِ الأول؛ فأيقن بكمالِ قدرةِ الله على كلِّ شيء؛ فمن أيقن بكمالِ قدرةِ الله آمن بالبعث، ومن جهله شكّ فيه؛ فاجعل يقينك بكمالِ قدرةِ الله بلا تعبٍ راسخًا؛ فبه تؤمن بالبعثِ وتعظّم الخالق."}}]},{"title":"الأمرُ بالصبرِ والتسبيح، والبعثِ والتذكيرِ بالقرآن","range":[39,45],"theme":"أمرُ النبيِّ بالصبرِ على ما يقولون والتسبيحِ قبل الطلوعِ والغروبِ ومن الليلِ وأدبارِ السجود، والاستماعِ ليومِ ينادي المنادي بالصيحةِ يومَ الخروج، وأنّ الله يحيي ويميت وإليه المصيرُ يومَ تشقّق الأرضُ حشرًا يسيرًا، وختامِ السورةِ بأنه أعلمُ بما يقولون وما هو عليهم بجبّارٍ فليذكّر بالقرآنِ من يخاف الوعيد","verses":[{"n":39,"reflection":{"text":"«فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب»: فاصبر، يا محمدُ، على ما يقوله المكذّبون، وسبّح بحمدِ ربّك قبل طلوعِ الشمسِ وقبل الغروب؛ ففي هذا الأمرُ بالصبرِ والتسبيح؛ فاصبر على أذى الناسِ واستعن بالتسبيحِ والذكر، فالصبرُ والتسبيحُ زادُ الداعيةِ وسلوانه، فالزمهما.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الأذى، والاستعانةُ بالتسبيحِ والذكر."},"action":{"text":"تأمّل الأمرَ بالصبرِ والتسبيح: فاصبر، يا محمدُ، على ما يقوله المكذّبون من التكذيبِ والأذى والاستهزاء، ولا يضق صدرك؛ وسبّح بحمدِ ربّك ونزّهه، مستعينًا بذلك على الصبر، قبل طلوعِ الشمسِ (صلاةَ الفجر) وقبل الغروب (صلاةَ العصرِ أو الظهرِ والعصر) «فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب»؛ ففي هذا الأمرُ بالصبرِ على أذى المكذّبين، والاستعانةِ على ذلك بالتسبيحِ والذكرِ والصلاة؛ فالصبرُ والتسبيحُ زادُ الداعيةِ وسلوانه؛ فاصبر أنت على أذى الناسِ وتكذيبهم واستهزائهم في سبيلِ الله؛ واستعن على الصبرِ بالتسبيحِ والذكرِ والصلاة؛ واصبر على ما يقولون واهجرهم هجرًا جميلًا؛ فاصبر لحكمِ ربّك ولا تكن كصاحبِ الحوت؛ واستعينوا بالصبرِ والصلاة؛ وكان يأمر أهله بالصلاةِ ويصطبر عليها؛ فالصبرُ والتسبيحُ يعينان على مشاقِّ الدعوةِ والحياة؛ فمن صبر واستعان بالذكرِ والصلاةِ ثبت ونُصِر، ومن جزع خسر؛ فاجعل الصبرَ على الأذى والاستعانةَ بالتسبيحِ والذكرِ دأبك."}},{"n":40,"reflection":{"text":"«ومن الليل فسبحه وأدبار السجود»، ومن الليلِ فسبّح ربّك (بصلاةِ الليل)، وسبّحه أدبارَ السجودِ (عقبَ الصلوات)؛ ففي هذا الأمرُ بتسبيحِ الليلِ وأدبارِ الصلوات؛ فأكثر من ذكرِ الله وتسبيحه في الليلِ وعقبَ الصلوات، فالتسبيحُ في هذه الأوقاتِ من أعظمِ الطاعات، فداوم عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من ذكرِ الله وتسبيحه في الليلِ وعقبَ الصلوات."},"action":{"text":"تأمّل الأمرَ بتسبيحِ الليلِ وأدبارِ الصلوات: ومن الليلِ فسبّح ربّك ونزّهه بصلاةِ الليلِ والتهجّدِ والذكر؛ وسبّحه أدبارَ السجودِ، أي عقبَ الصلواتِ المكتوبةِ بالتسبيحِ والتحميدِ والتكبيرِ والذكر، أو ركعتي الفجرِ أو الوترِ بعد صلاةِ الليل «ومن الليل فسبحه وأدبار السجود»؛ ففي هذا الأمرُ بتسبيحِ الله وذكره في الليلِ (بالتهجّد)، وأدبارِ الصلوات (بالأذكارِ عقبها)؛ فهذه أوقاتُ فضلٍ للذكرِ والتسبيح؛ فأكثر أنت من ذكرِ الله وتسبيحه في الليلِ بصلاةِ التهجّد؛ ومن الليلِ فتهجّد به نافلةً لك؛ كانوا قليلًا من الليلِ ما يهجعون؛ تتجافى جنوبهم عن المضاجع يدعون ربّهم خوفًا وطمعًا؛ وسبّح ربّك عقبَ الصلواتِ بالأذكارِ المأثورة؛ من سبّح الله دبرَ كلِّ صلاةٍ ثلاثًا وثلاثين... غُفِرت خطاياه؛ فالتسبيحُ في الليلِ وأدبارِ الصلواتِ من أعظمِ الطاعاتِ وأزكاها؛ فمن داوم عليه نال الفضلَ والقرب، ومن غفل عنه حُرِم؛ فاجعل الإكثارَ من الذكرِ والتسبيحِ في الليلِ وعقبَ الصلواتِ دأبك."}},{"n":41,"reflection":{"text":"«واستمع يوم يناد المناد من مكان قريب»، واستمع، يا محمدُ، يومَ ينادي المنادي بالبعثِ من مكانٍ قريبٍ يسمعه الجميع؛ ففي هذا التذكيرُ بنداءِ البعث؛ فاستعدّ ليومِ النداءِ بالبعثِ الذي يسمعه كلُّ أحد، فالبعثُ حقٌّ قريب، فاعمل له قبل مجيئه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ النداءِ بالبعث، والعملُ له."},"action":{"text":"تأمّل التذكيرَ بنداءِ البعث: واستمع، يا محمدُ، وانتظر يومَ ينادي المنادي (إسرافيلُ أو مَلَكٌ) بالنفخةِ الثانيةِ للبعثِ من مكانٍ قريبٍ يسمعه الخلائقُ كلُّهم على السواء؛ فيقومون من قبورهم «واستمع يوم يناد المناد من مكان قريب»؛ ففي هذا التذكيرُ بيومِ البعث، حين ينادي المنادي فيسمعه الجميعُ من قربٍ فيقومون؛ فاستعدّ أنت لذلك اليومِ الذي يُنادى فيه بالبعثِ فيسمعه كلُّ أحد؛ يومَ يدعوكم فتستجيبون بحمده؛ يومَ يسمعون الصيحةَ بالحق؛ ما ينظرون إلا صيحةً واحدةً تأخذهم؛ فالبعثُ حقٌّ قريبٌ آتٍ لا محالة؛ فاعمل له بالإيمانِ والعملِ الصالحِ قبل مجيئه؛ فمن استعدّ ليومِ النداءِ بالبعثِ بالعملِ نجا، ومن غفل عنه خسر؛ فاجعل الاستعدادَ ليومِ البعثِ والعملَ له دأبك."}},{"n":42,"reflection":{"text":"«يوم يسمعون الصيحة بالحق ذلك يوم الخروج»: يومَ يسمعون صيحةَ البعثِ بالحقِّ الذي لا شكَّ فيه، ذلك يومُ الخروجِ من القبور؛ ففي هذا بيانُ يومِ الخروج؛ فاستعدّ ليومِ الخروجِ من القبور، فالبعثُ حقٌّ، فاعمل ليومِ خروجك من القبرِ قبل مجيئه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ الخروجِ من القبور، والعملُ له."},"action":{"text":"تأمّل يومَ الخروج: يومَ يسمع الخلائقُ صيحةَ البعثِ والنفخةَ الثانيةَ بالحقِّ الذي لا شكَّ فيه ولا مفرَّ منه؛ ذلك اليومُ هو يومُ الخروجِ من القبورِ للحسابِ والجزاء «يوم يسمعون الصيحة بالحق ذلك يوم الخروج»؛ ففي هذا بيانُ أنّ صيحةَ البعثِ تكون بالحق، وأنّ ذلك اليومَ هو يومُ الخروجِ من القبور؛ فيسمعون الصيحةَ فيخرجون؛ فاستعدّ أنت ليومِ الخروجِ من القبور؛ فإنه حقٌّ آتٍ لا محالة؛ إن كانت إلا صيحةً واحدةً فإذا هم جميعٌ لدينا محضرون؛ يومَ يخرجون من الأجداثِ سراعًا؛ فبادر بالعملِ الصالحِ والتوبةِ قبل يومِ الخروج؛ فمن استعدّ ليومِ الخروجِ بالعملِ نجا، ومن غفل عنه خسر؛ فاجعل الاستعدادَ ليومِ الخروجِ من القبورِ والعملَ له دأبك."}},{"n":43,"reflection":{"text":"«إنا نحن نحيي ونميت وإلينا المصير»: إنا نحن نحيي الخلقَ ونميتهم، وإلينا المرجعُ والمصير؛ ففي هذا تقريرُ الإحياءِ والإماتةِ والمرجع؛ فاعلم أنّ الله وحده يحيي ويميت وإليه ترجع، فاستعدّ للمصيرِ إليه، فمن يحيي ويميت إليه المرجعُ والحساب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للمصيرِ إلى الله، وإفرادُه بالإحياءِ والإماتة."},"action":{"text":"تأمّل تقريرَ الإحياءِ والمصير: إنا نحن وحدنا نحيي الخلقَ بعد العدم، ونميتهم عند انقضاءِ آجالهم، لا يقدر على ذلك غيرنا؛ وإلينا المصيرُ والمرجعُ يومَ القيامةِ للحسابِ والجزاء «إنا نحن نحيي ونميت وإلينا المصير»؛ ففي هذا تقريرُ أنّ الله وحده هو المحيي المميت، وأنّ المرجعَ إليه؛ فبيده الإحياءُ والإماتةُ والمصير؛ فاعلم أنت أنّ الله وحده يحيي ويميت، وأنّ مرجعك إليه؛ هو يحيي ويميت وإليه ترجعون؛ وأنه هو أماتَ وأحيا؛ كيف تكفرون بالله وكنتم أمواتًا فأحياكم ثم يميتكم ثم يحييكم ثم إليه تُرجَعون؛ فاستعدّ للمصيرِ إلى الله بالإيمانِ والعملِ الصالح؛ فمن يحيي ويميت إليه المرجعُ والحساب؛ فمن استعدّ للمصيرِ إلى الله فاز، ومن غفل عنه خسر؛ فاجعل الاستعدادَ للمصيرِ إلى الله بالعملِ الصالحِ دأبك."}},{"n":44,"reflection":{"text":"«يوم تشقق الأرض عنهم سراعا ذلك حشر علينا يسير»: يومَ تتشقّق الأرضُ عنهم فيخرجون مسرعين، ذلك حشرٌ يسيرٌ علينا؛ ففي هذا بيانُ يسرِ الحشرِ على الله؛ فاعلم أنّ حشرك وبعثك يسيرٌ على الله، فلا تستبعده، فمن يشقّ الأرضَ ويحشر الخلقَ حشره عليه يسير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بيسرِ الحشرِ على الله، وعدمُ استبعادِ البعث."},"action":{"text":"تأمّل يسرَ الحشر: يومَ تتشقّق الأرضُ عن الموتى فيخرجون منها مسرعين إلى الداعي؛ ذلك الحشرُ والجمعُ حشرٌ يسيرٌ هيّنٌ علينا، لا صعوبةَ فيه ولا مشقّة «يوم تشقق الأرض عنهم سراعا ذلك حشر علينا يسير»؛ ففي هذا بيانُ أنّ حشرَ الخلقِ وبعثهم يسيرٌ هيّنٌ على الله؛ فتشقّق الأرضُ فيخرجون سراعًا، ويُحشَرون بلا عناءٍ على الله؛ فاعلم أنت أنّ حشرك وبعثك يسيرٌ على الله لا يعجزه؛ فلا تستبعد البعثَ والحشر؛ ما خلقكم ولا بعثكم إلا كنفسٍ واحدة؛ وما أمرُ الساعةِ إلا كلمحِ البصرِ أو هو أقرب؛ يومَ يدعوكم فتستجيبون بحمده وتظنّون إن لبثتم إلا قليلًا؛ فمن يشقّ الأرضَ ويحشر الخلقَ في لحظةٍ حشره عليه يسير؛ فأيقن بالبعثِ والحشرِ واستعدّ له؛ فمن أيقن بيسرِ الحشرِ على الله آمن بالبعث، ومن استبعده أنكره؛ فاجعل يقينك بيسرِ الحشرِ على الله والاستعدادَ له دأبك."}},{"n":45,"reflection":{"text":"«نحن أعلم بما يقولون وما أنت عليهم بجبار فذكر بالقرآن من يخاف وعيد»: نحن أعلم بما يقول المكذّبون، وما أنت، يا محمدُ، عليهم بمسلّطٍ تجبرهم على الإيمان، فذكّر بالقرآنِ من يخاف وعيدي؛ ففي هذا بيانُ وظيفةِ النبيِّ في التذكيرِ لا الإجبار؛ فذكّر بالقرآنِ ولا تحمل همَّ إجبارِ الناس، فالتذكيرُ بالقرآنِ ينفع من يخاف الوعيد، فاجعل القرآنَ وسيلةَ تذكيرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكيرُ بالقرآنِ دون إجبارِ الناس، وإدراكُ أنه ينفع الخائفين."},"action":{"text":"تأمّل وظيفةَ النبيِّ في التذكير: نحن أعلم بما يقوله المكذّبون من التكذيبِ والأذى، فلا يهمّنك ذلك؛ وما أنت، يا محمدُ، عليهم بجبّارٍ مسلّطٍ تجبرهم على الإيمانِ وتقهرهم عليه؛ فما عليك إلا البلاغ؛ فذكّر بالقرآنِ من يخاف وعيدي وعذابي، فإنه المنتفع بالتذكير «نحن أعلم بما يقولون وما أنت عليهم بجبار فذكر بالقرآن من يخاف وعيد»؛ ففي هذا بيانُ أنّ وظيفةَ النبيِّ التذكيرُ والبلاغُ لا الإجبارُ والإكراه، وأنّ المنتفعَ بالتذكيرِ من يخاف الوعيد؛ فليس عليه إكراهُ الناسِ على الإيمان؛ فذكّر أنت بالقرآنِ وبلّغ، ولا تحمل همَّ إجبارِ الناسِ على الهداية؛ فلست عليهم بمصيطر؛ لا إكراهَ في الدين؛ أفأنت تكره الناسَ حتى يكونوا مؤمنين؛ إنما أنت مذكّر لست عليهم بمصيطر؛ فالتذكيرُ بالقرآنِ ينفع من يخاف الوعيدَ ويرجو الثواب؛ فذكّر إن نفعتِ الذكرى، سيذّكّر من يخشى؛ فمن ذكّر بالقرآنِ وبلّغ أدّى ما عليه، وانتفع به من يخاف الوعيد؛ فاجعل التذكيرَ بالقرآنِ وسيلةَ دعوتك، ولا تحمل ما ليس إليك من الهداية؛ فبالتذكيرِ بالقرآنِ ينتفع الخائفون من وعيدِ الله."}}]}],"coverage":{"covered":45,"total":45}};
